-- ----------------------------
-- Table structure for bet_records
-- ----------------------------
DROP TABLE IF EXISTS `bet_records`;
CREATE TABLE `bet_records`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bet_record_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `pf_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `pf_sub_pf_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `pf_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `origin_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `round_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `game_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bet_status` enum('赢','输') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `bet` decimal(15, 4) NULL DEFAULT 0.0000,
  `bet_valid` decimal(15, 4) NULL DEFAULT 0.0000,
  `profit` decimal(15, 4) NULL DEFAULT 0.0000,
  `tax` decimal(15, 4) NULL DEFAULT 0.0000,
  `result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `is_single_wallet` tinyint(1) NULL DEFAULT 0,
  `round_end_at` datetime NULL DEFAULT NULL,
  `common_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `purchase_method` int(11) NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_bet_record`(`bet_record_id` ASC) USING BTREE,
  INDEX `idx_account`(`pf_account` ASC) USING BTREE,
  INDEX `idx_game`(`game_code` ASC) USING BTREE,
  INDEX `idx_time`(`round_end_at` ASC) USING BTREE,
  INDEX `idx_status`(`bet_status` ASC) USING BTREE,
  INDEX `idx_profit`(`profit` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_askme_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_askme_bet_raw_log`;
CREATE TABLE `tb_askme_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `bet_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注标识符',
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `game_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏名称',
  `game_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏标识符',
  `product` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏提供商',
  `round_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '回合标识符',
  `categories` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏分类',
  `winlose` decimal(15, 2) NOT NULL COMMENT '输赢金额',
  `turnover` decimal(15, 2) NOT NULL COMMENT '流水金额',
  `bet` decimal(15, 2) NOT NULL COMMENT '下注金额',
  `timestamp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易时间',
  `is_end_round` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否结束回合（1=True，0=False）',
  `is_freespin` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为免费旋转（1=True，0=False）',
  `is_buy_feature` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为购买功能（1=True，0=False）',
  `is_gamble` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为赌博功能（1=True，0=False）',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始注单JSON数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bet_id`(`bet_id` ASC) USING BTREE,
  INDEX `idx_timestamp`(`timestamp` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 76809 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'ASKME原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_aw_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_aw_bet_raw_log`;
CREATE TABLE `tb_aw_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员唯一识别值',
  `wagers_id` bigint(20) NOT NULL COMMENT '游戏内注单唯一值',
  `game_id` int(11) NOT NULL COMMENT '游戏的唯一识别值',
  `wagers_time` datetime NOT NULL COMMENT '投注时间(GMT-4 时区)',
  `bet_amount` decimal(16, 4) NOT NULL COMMENT '投注金额(游戏币)',
  `payoff_time` datetime NULL DEFAULT NULL COMMENT '派彩时间(GMT-4 时区)',
  `payoff_amount` decimal(16, 4) NOT NULL COMMENT '派彩金额(游戏币)',
  `status` int(11) NOT NULL COMMENT '注单状态: 1-赢, 2-输, 3-平局',
  `settlement_time` datetime NOT NULL COMMENT '对账时间(GMT-4 时区)',
  `game_category_id` int(11) NOT NULL COMMENT '游戏类型ID',
  `type` int(11) NOT NULL COMMENT '注单类型',
  `agent_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员所属站长唯一识别值',
  `turnover` decimal(16, 4) NOT NULL COMMENT '有效投注金额(游戏币)',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注單json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `wagers_id_IDX`(`wagers_id` ASC) USING BTREE,
  INDEX `idx_wagers_time`(`wagers_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33430 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AW游戏原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_bet_compare_result
-- ----------------------------
DROP TABLE IF EXISTS `tb_bet_compare_result`;
CREATE TABLE `tb_bet_compare_result`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '游戏厂商代码',
  `compare_date` datetime NOT NULL COMMENT '对账时间段开始时间（整点小时）',
  `compare_end_time` datetime NOT NULL COMMENT '对账时间段结束时间',
  `compare_time` datetime NOT NULL COMMENT '对账执行时间',
  `std_bet_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '标准表投注金额',
  `std_order_count` bigint(20) NULL DEFAULT 0 COMMENT '标准表注单数量',
  `std_win_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '标准表中奖金额',
  `std_valid_bet_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '标准表有效投注金额',
  `std_win_lose_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '标准表输赢金额',
  `raw_order_count` bigint(20) NULL DEFAULT 0 COMMENT '原始表注单数量',
  `raw_bet_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '原始表投注金额',
  `raw_win_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '原始表中奖金额',
  `raw_valid_bet_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '原始表有效投注金额',
  `order_count_diff` bigint(20) NULL DEFAULT 0 COMMENT '注单数量差异',
  `bet_amount_diff` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '投注金额差异',
  `win_amount_diff` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '中奖金额差异',
  `valid_bet_amount_diff` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '有效投注金额差异',
  `is_match` tinyint(2) NOT NULL DEFAULT 0 COMMENT '是否一致: 0-不一致, 1-一致',
  `match_status` tinyint(2) NOT NULL DEFAULT 0 COMMENT '匹配状态: 0-未对账, 1-完全一致, 2-数量不一致, 3-金额不一致, 4-异常',
  `error_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_provider_hour`(`provider` ASC, `compare_date` ASC) USING BTREE,
  INDEX `idx_compare_date`(`compare_date` ASC) USING BTREE,
  INDEX `idx_is_match`(`is_match` ASC) USING BTREE,
  INDEX `idx_match_status`(`match_status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 975 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '注单对账结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_bg_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_bg_bet_raw_log`;
CREATE TABLE `tb_bg_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单ID',
  `uid` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SN',
  `login_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登录ID',
  `module_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模块名称',
  `from_ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注来源IP',
  `table_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏桌台编号',
  `issue_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注期数',
  `play_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法ID，唯一标识一种注单类别',
  `play_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法名称',
  `play_name_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法名称(En)',
  `game_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `module_id` int(11) NULL DEFAULT NULL COMMENT '模块ID',
  `game_id` int(11) NULL DEFAULT NULL COMMENT '游戏ID',
  `order_status` int(11) NULL DEFAULT NULL COMMENT '订单状态',
  `order_from` int(11) NULL DEFAULT NULL COMMENT '订单来源',
  `order_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `last_update_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON',
  `game_balance` decimal(20, 2) NULL DEFAULT NULL COMMENT '下注后帐户的余额',
  `win_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '派彩额',
  `bet_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '下注额',
  `extend` decimal(20, 2) NULL DEFAULT NULL COMMENT '扩展字段',
  `valid_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '打码量(有效投注)',
  `payout` decimal(20, 2) NULL DEFAULT NULL COMMENT '派彩(输赢)',
  `fire_count` int(11) NULL DEFAULT NULL COMMENT '发炮数量',
  `jackpot_type` int(11) NULL DEFAULT NULL COMMENT '奖池类型，默认为0(默认值为0，即打中宝箱并获得彩金）',
  `jackpot` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'JP中奖',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户 ID',
  `staff_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '荷官工号',
  `amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '金额',
  `tip_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '小费 ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_id`(`order_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_uid`(`uid` ASC) USING BTREE,
  INDEX `idx_order_time`(`order_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7520 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'BG原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_bng_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_bng_bet_raw_log`;
CREATE TABLE `tb_bng_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家当前游戏动作，例如：spin、respin、freespin、buy_spin等',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易的UID, 32字母和数字组成',
  `original_transaction_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '回滚时的原交易ID, 其他为null',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易类型，例如：COMMIT 或 ROLLBACK',
  `player_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家ID',
  `brand` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '站点名称， \"*\" 为预设站点',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ISO-4217货币代码',
  `mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏模式，例如：REAL 或 FUN',
  `is_test` tinyint(1) NULL DEFAULT NULL COMMENT '是否为测试用户，true/false',
  `platform` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏平台，DESKTOP 或 MOBILE',
  `tag` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签，来自多钱包的 get_player_token 指令，或单钱包的 login 指令',
  `round_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易回合ID，一个回合可能有多个交易',
  `round_started` tinyint(1) NULL DEFAULT NULL COMMENT '回合是否开始',
  `round_finished` tinyint(1) NULL DEFAULT NULL COMMENT '回合是否结束',
  `bet` decimal(10, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `win` decimal(10, 2) NULL DEFAULT NULL COMMENT '赢得金额',
  `balance_after` decimal(10, 2) NULL DEFAULT NULL COMMENT '交易后的余额',
  `auto_paid` tinyint(1) NULL DEFAULT NULL COMMENT '是否自动派彩',
  `provider_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商ID',
  `provider_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商名称',
  `game_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏ID',
  `game_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易状态，可能值包括：OK、NEW、LOCKED、EXCEED',
  `manual_confirmed` tinyint(1) NULL DEFAULT NULL COMMENT '是否从后台手动确认该交易',
  `c_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '交易创建时间，UTC 格式',
  `bonus_id` bigint(20) NULL DEFAULT NULL COMMENT '奖励ID',
  `campaign` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '活动名称，奖金注单时存在',
  `bonus_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖金来源，例如：OPERATOR 或 PROVIDER',
  `ext_bonus_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖金注单中的奖金ID，来自运营商或供应商',
  `bonus_event` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖金事件类型，例如：TOURNAMENT、JACKPOT 等',
  `bonus_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖金类型，例如：FIXED_FREEBET、FLEXIBLE_FREEBET',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `transaction_id_idx`(`transaction_id` ASC) USING BTREE,
  UNIQUE INDEX `id`(`id` ASC) USING BTREE,
  INDEX `idx_c_at`(`c_at` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7605 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'BNG原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_cmd_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_cmd_bet_raw_log`;
CREATE TABLE `tb_cmd_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `original_id` bigint(20) NOT NULL COMMENT '供查询的自增ID',
  `source_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员在合作商平台的标识',
  `reference_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单单号',
  `soc_trans_id` int(11) NOT NULL COMMENT '注单系统ID',
  `is_first_half` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是上半场',
  `trans_date` bigint(20) NOT NULL COMMENT 'CMD用户下注时间, Ticks数据',
  `is_home_give` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为主队让球',
  `is_bet_home` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为投注主队',
  `bet_amount` decimal(18, 2) NOT NULL COMMENT '注单下注金额',
  `outstanding` decimal(18, 4) NOT NULL COMMENT '用户未结算金额',
  `hdp` decimal(18, 2) NULL DEFAULT NULL COMMENT '让球数',
  `odds` decimal(18, 2) NOT NULL COMMENT '投注赔率',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币代码',
  `win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '输赢金额',
  `exchange_rate` decimal(18, 2) NULL DEFAULT NULL COMMENT '会员货币转换为马币的汇率',
  `win_lose_status` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '输赢状态:WA=全胜,WH=赢一半,LA=全输,LH=输一半,D=平局,P=待定',
  `trans_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法类型',
  `danger_status` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单状态:D=处理中,N=已接受早盘,A=已接受滚球,C=已取消,R=已拒绝',
  `mem_commission` decimal(18, 2) NULL DEFAULT NULL COMMENT '会员所得佣金',
  `bet_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家投注时IP',
  `home_score` int(11) NULL DEFAULT NULL COMMENT '主队得分',
  `away_score` int(11) NULL DEFAULT NULL COMMENT '客队得分',
  `run_home_score` int(11) NULL DEFAULT NULL COMMENT '投注时主队得分',
  `run_away_score` int(11) NULL DEFAULT NULL COMMENT '投注时客队得分',
  `is_running` tinyint(1) NULL DEFAULT 0 COMMENT '是否为滚球',
  `reject_reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单拒绝原因',
  `sport_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '运动项目',
  `choice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注位置',
  `working_date` int(11) NULL DEFAULT NULL COMMENT '注单赛事工作日',
  `odds_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率类型:MY=马来盘,ID=印度尼西亚盘,HK=香港盘,DE=欧洲盘,US=美国盘',
  `match_date` bigint(20) NULL DEFAULT NULL COMMENT '球赛开赛日期',
  `home_team_id` int(11) NULL DEFAULT NULL COMMENT '主队ID',
  `away_team_id` int(11) NULL DEFAULT NULL COMMENT '客队ID',
  `league_id` int(11) NULL DEFAULT NULL COMMENT '联赛ID',
  `special_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特别投注ID',
  `status_change` int(11) NULL DEFAULT 0 COMMENT '是否重算标识(>=2标识该单有重算)',
  `state_update_ts` bigint(20) NULL DEFAULT NULL COMMENT '注单结算时间',
  `mem_commission_set` decimal(18, 4) NULL DEFAULT NULL COMMENT '佣金设定值',
  `is_cash_out` tinyint(1) NULL DEFAULT 0 COMMENT '注单是否卖单',
  `cash_out_total` decimal(18, 4) NULL DEFAULT NULL COMMENT '注单卖单数量',
  `cash_out_take_back` decimal(18, 4) NULL DEFAULT NULL COMMENT '注单卖单所得金额',
  `cash_out_win_lose_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '注单卖单输赢值',
  `bet_source` int(11) NULL DEFAULT NULL COMMENT '下注平台:1=Desktop,7=Mobile(v1),9=New Mobile(v1),10=Mobile E-Sport(v3),11=New Mobile E-Sport(v3),12=ES PC网,14=VS PC网,15=VS PC 亚洲版,16=VS 手机网',
  `aos_excluding` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '如果下注AOS则为不包括在AOS内的比分',
  `mmr_percent` decimal(18, 4) NULL DEFAULT NULL COMMENT 'MMR百分比',
  `match_id` int(11) NULL DEFAULT NULL COMMENT '注单赛事ID',
  `match_group_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单赛事系统ID',
  `bet_remarks` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'OddsTrader系统专用值',
  `is_special` tinyint(1) NULL DEFAULT 0 COMMENT '是否是特别投注',
  `details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '详情：子注单或者卖单',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_cmd_bet_raw_log_reference_no_IDX`(`reference_no` ASC) USING BTREE,
  INDEX `idx_trans_date`(`trans_date` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3772 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CMD投注记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_cq9_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_cq9_bet_raw_log`;
CREATE TABLE `tb_cq9_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `gameplat` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏平台 (web 或 mobile)',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员游戏账户',
  `round` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单订单号',
  `gamecode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏code',
  `balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '余额，最大为 20 位数字，精确到小数点后 4 位',
  `win` decimal(20, 4) NULL DEFAULT NULL COMMENT '游戏赢分，最大为 20 位数字，精确到小数点后 4 位',
  `bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `validbet` decimal(20, 4) NULL DEFAULT NULL COMMENT '有效下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注状态:',
  `bettime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注时间 (可以选择改为时间戳类型)',
  `raw_createtime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '當筆資料建立時間(原来字段是createtime)',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币类型',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '接口返回结果，使用 TEXT 类型存储 JSON 数据',
  `tracecode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接口响应标识',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(32) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(32) NULL DEFAULT NULL COMMENT '更新时间',
  `gametype` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏品类：slot-老虎機，fish-捕魚遊戲,arcade-街機遊戲，table-桌上遊戲，live-真人視訊,lotto-彩票遊戲 dealergame-荷官發牌遊戲 sports-體育,livegame-彈珠遊戲,animal-鬥雞',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商code',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注详情',
  `tickettype` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免費券類型\r\n1 = 免費遊戲 ( 獲得一局 free game )\r\n2 = 免費 spin ( 獲得一次 free spin )',
  `ticketid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免費券id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `round_index`(`round` ASC) USING BTREE,
  INDEX `gp_code_index`(`gp_code` ASC) USING BTREE,
  INDEX `idx_bettime`(`bettime` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 244441 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'cq9原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_cr_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_cr_bet_raw_log`;
CREATE TABLE `tb_cr_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `original_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易單序號',
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易單會員名稱',
  `mid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '會員編號',
  `gtype` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '球類(FT:足球,BK:籃球/美足,TN:網球,BS:棒球,OP:其他,VF:虛擬足球,SK:台球,MT:跨球類過關,FS:冠軍,VB:排球,TT:乒乓球,BM:羽毛球,ES:電子競技)',
  `wtype` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法',
  `wtypecode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法原始資料',
  `rtype` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法',
  `rtypecode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法原始資料',
  `strong` enum('','H','C') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '強弱 H：主隊為強隊 C：客隊為強隊',
  `odds` enum('H','M','I','E') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盤口類型(H=香港,M=馬來,I=印尼,E=歐洲)',
  `order` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '玩法細項',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '幣別',
  `gold` decimal(18, 2) NULL DEFAULT NULL COMMENT '下注金額(會員貨幣)',
  `gold_d` decimal(18, 2) NULL DEFAULT NULL COMMENT '下注金額(站別貨幣)',
  `parlaysub` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '串數內容',
  `parlaynum` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '串數',
  `ioratio` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易單當下使用的賠率',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易單 IP',
  `adddate` datetime NOT NULL COMMENT '交易單的日期時間',
  `resultdate` datetime NULL DEFAULT NULL COMMENT '算結果的日期時間',
  `orderdate` date NULL DEFAULT NULL COMMENT '開賽日期',
  `ordertime` time NULL DEFAULT NULL COMMENT '開賽時間',
  `settle` enum('0','1') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '0:無結果 1:有結果',
  `result` enum('0','L','W','P','D','A') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '0:未有結果 L:輸 W:贏 P:和 D:取消 A:還原',
  `resultdetail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '結果詳細資料',
  `wingold_d` decimal(18, 2) NULL DEFAULT NULL COMMENT '可贏金額/輸贏金額(站別貨幣)',
  `wingold` decimal(18, 2) NULL DEFAULT NULL COMMENT '可贏金額/輸贏金額(會員貨幣)',
  `oddsformat` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '球頭',
  `league` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '聯盟名稱',
  `tname_away` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客隊名稱',
  `tname_home` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主隊名稱',
  `handicap` enum('1','2') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '1:單盤 2:雙盤',
  `result_score` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有結果全場比分',
  `pname` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '節次名稱',
  `score` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '未有結果滾球當下比分',
  `vgold` decimal(18, 2) NULL DEFAULT NULL COMMENT '有效金額',
  `members_vgold` decimal(18, 2) NULL DEFAULT NULL COMMENT '有效金額(會員貨幣)',
  `degold` decimal(18, 2) NULL DEFAULT NULL COMMENT '實際扣除額(會員貨幣)',
  `degold_d` decimal(18, 2) NULL DEFAULT NULL COMMENT '實際扣除額(站別貨幣)',
  `cashoutid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '兌現關聯母單',
  `cashout` decimal(18, 2) NULL DEFAULT NULL COMMENT '兌現金額(會員貨幣)',
  `cashout_d` decimal(18, 2) NULL DEFAULT NULL COMMENT '兌現金額(站別貨幣)',
  `report_test` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '測試',
  `reserve_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '預約流水編號',
  `reserve_status` enum('','N','D','Y') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '預約注單狀態 空白:注單預約中 N:注單失敗 D:注單取消 Y:注單成立',
  `wid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易單流水編號',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注單json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_cr_bet_raw_log_original_id_IDX`(`original_id` ASC) USING BTREE,
  INDEX `idx_adddate`(`adddate` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25004 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CR投注記錄表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_db_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_db_bet_raw_log`;
CREATE TABLE `tb_db_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `member_id` bigint(20) NULL DEFAULT NULL COMMENT '会员ID',
  `member_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员账号',
  `merchant_id` bigint(20) NULL DEFAULT NULL COMMENT '商户ID',
  `merchant_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户账号',
  `parent_merchant_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上级商户账号',
  `parent_merchant_id` bigint(20) NULL DEFAULT NULL COMMENT '上级商户ID',
  `tester` int(11) NULL DEFAULT NULL COMMENT '是否测试用户 0-正式用户 1-测试用户',
  `order_type` int(11) NULL DEFAULT NULL COMMENT '注单类型',
  `parley_type` int(11) NULL DEFAULT NULL COMMENT '串关类型',
  `game_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏ID',
  `tournament_id` bigint(20) NULL DEFAULT NULL COMMENT '联赛ID',
  `match_id` bigint(20) NULL DEFAULT NULL COMMENT '比赛ID',
  `match_type` int(11) NULL DEFAULT NULL COMMENT '比赛类型',
  `market_id` bigint(20) NULL DEFAULT NULL COMMENT '盘口ID',
  `market_cn_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口中文名称',
  `market_en_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口英文名称',
  `team_names` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '队伍名称',
  `odd_id` bigint(20) NULL DEFAULT NULL COMMENT '赔率ID',
  `odd_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率名称',
  `odd_en_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率英文名称',
  `round` int(11) NULL DEFAULT NULL COMMENT '轮次',
  `odd` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率值',
  `bet_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '投注金额',
  `win_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '中奖金额',
  `is_live` int(11) NULL DEFAULT NULL COMMENT '是否滚球 0-非滚球 1-滚球',
  `bet_status` int(11) NULL DEFAULT NULL COMMENT '投注状态',
  `confirm_type` int(11) NULL DEFAULT NULL COMMENT '确认类型',
  `bet_time` bigint(20) NULL DEFAULT NULL COMMENT '投注时间',
  `settle_time` bigint(20) NULL DEFAULT NULL COMMENT '结算时间',
  `match_start_time` bigint(20) NULL DEFAULT NULL COMMENT '比赛开始时间',
  `settle_count` int(11) NULL DEFAULT NULL COMMENT '结算次数',
  `team_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '队伍ID',
  `device` int(11) NULL DEFAULT NULL COMMENT '设备类型',
  `bet_ip` bigint(20) NULL DEFAULT NULL COMMENT '投注IP',
  `team_cn_names` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '队伍中文名称',
  `team_en_names` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '队伍英文名称',
  `score_benchmark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基准分',
  `currency_code` int(11) NULL DEFAULT NULL COMMENT '货币代码',
  `exchange_rate` decimal(10, 6) NULL DEFAULT NULL COMMENT '汇率',
  `live_score` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实时比分',
  `tournament` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联赛名称',
  `tournament_en` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联赛英文名称',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON数据',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '详情信息',
  `order_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `status` int(11) NULL DEFAULT NULL COMMENT '状态',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `odd_type` int(11) NULL DEFAULT NULL COMMENT '盘口类型',
  `tournament_json` json NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_match_id`(`match_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_merchant_id`(`merchant_id` ASC) USING BTREE,
  INDEX `idx_order_no`(`order_id` ASC) USING BTREE,
  INDEX `idx_member_id`(`member_id` ASC) USING BTREE,
  INDEX `idx_settle_time`(`settle_time` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_game_id`(`game_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 384 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'DB投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_dct_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_dct_bet_raw_log`;
CREATE TABLE `tb_dct_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `brand_uid` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户玩家ID',
  `currency` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '币别',
  `wager_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '下注类型',
  `amount` decimal(16, 6) NULL DEFAULT NULL COMMENT '金额',
  `before_amount` decimal(16, 6) NULL DEFAULT NULL COMMENT '交易前余额',
  `after_amount` decimal(16, 6) NULL DEFAULT NULL COMMENT '交易后余额',
  `game_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏ID',
  `game_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `round_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '局号',
  `wager_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '下注ID',
  `jackpot_contribution` decimal(16, 4) NULL DEFAULT 0.0000 COMMENT '彩金贡献',
  `jackpot_win` decimal(16, 4) NULL DEFAULT 0.0000 COMMENT '彩金赢取',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `bet_create_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `game_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '游戏结果',
  `tip` decimal(16, 4) NULL DEFAULT 0.0000 COMMENT '小费',
  `is_endround` tinyint(1) NULL DEFAULT 0 COMMENT '是否结束回合',
  `provider` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏商',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始响应JSON',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wager_id`(`wager_id` ASC) USING BTREE,
  INDEX `idx_round_id`(`round_id` ASC) USING BTREE,
  INDEX `idx_bet_create_time`(`bet_create_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'DCT原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_dg_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_dg_bet_raw_log`;
CREATE TABLE `tb_dg_bet_raw_log`  (
  `id` bigint(20) NOT NULL COMMENT '注单ID(唯一)',
  `table_id` int(11) NULL DEFAULT NULL COMMENT '游戏桌号(红包小费记录没有)',
  `shoe_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏靴号(红包小费记录没有)',
  `play_id` bigint(20) NULL DEFAULT NULL COMMENT '当靴局号(红包小费记录没有)',
  `lobby_id` int(11) NULL DEFAULT NULL COMMENT '游戏厅号(1:旗舰厅; 2:亚洲厅; 3,4:现场厅; 5:性感厅; 6:越南厅; 8,9:区块链厅)',
  `game_type` int(11) NULL DEFAULT NULL COMMENT '注单类型(1:注单，2:红包小费)',
  `game_id` int(11) NULL DEFAULT NULL COMMENT '游戏类型(百家乐，龙虎...)',
  `bet_time` datetime NULL DEFAULT NULL COMMENT '下注时间',
  `cal_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `win_or_loss` decimal(18, 2) NULL DEFAULT NULL COMMENT '派彩金额(含本金)',
  `balance_before` decimal(18, 2) NULL DEFAULT NULL COMMENT '下注前余额(仅作参考)',
  `bet_points` decimal(18, 2) NULL DEFAULT NULL COMMENT '下注金额(下注扣款金额)',
  `available_bet` decimal(18, 2) NULL DEFAULT NULL COMMENT '洗码金额(用于计算佣金)',
  `user_name` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员账号([a-zA-Z0-9@#_]{3,40})',
  `result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏结果',
  `bet_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单详情',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户端IP',
  `ext` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏唯一局号',
  `is_revocation` int(11) NULL DEFAULT NULL COMMENT '结算状态(0:未结算,1:已结算,2:已撤销,3:冻结)',
  `parent_bet_id` bigint(20) NULL DEFAULT NULL COMMENT '改单时对应的注单记录',
  `currency_id` int(11) NULL DEFAULT NULL COMMENT '币种ID',
  `device_type` int(11) NULL DEFAULT NULL COMMENT '客户端平台ID(1:PC,2:安卓,3:苹果,5:H5)',
  `transfers` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '钱包扣款记录(转账模式API没有)',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `bet_order_no` bigint(11) NULL DEFAULT NULL COMMENT '注单号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `bet_order_no_index`(`bet_order_no` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'DG游戏原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_evo_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_evo_bet_raw_log`;
CREATE TABLE `tb_evo_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `txn_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单ID',
  `prd_id` int(11) NOT NULL COMMENT '产品ID',
  `game_id` int(11) NOT NULL COMMENT '游戏ID',
  `table_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桌子ID',
  `round_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '局ID',
  `user_id` bigint(20) NOT NULL COMMENT '会员ID',
  `username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员名称',
  `stake` decimal(18, 6) NULL DEFAULT NULL COMMENT '下注金额',
  `payout` decimal(18, 6) NULL DEFAULT NULL COMMENT '盈利金额',
  `balance` decimal(18, 6) NULL DEFAULT NULL COMMENT '会员余额',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单状态类型',
  `created_at` datetime NULL DEFAULT NULL COMMENT '注单生成时间',
  `settled_at` datetime NULL DEFAULT NULL COMMENT '注单结算时间',
  `bonus_amount` decimal(18, 6) NULL DEFAULT NULL COMMENT '奖金金额',
  `bonus_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖金类型',
  `bonus_created_at` datetime NULL DEFAULT NULL COMMENT '奖金生成时间',
  `error` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_evo_bet_raw_log_txn_id_IDX`(`txn_id` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1404 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WC注单及奖金原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_fast_spin_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_fast_spin_bet_raw_log`;
CREATE TABLE `tb_fast_spin_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_id` bigint(20) NOT NULL COMMENT '票据ID',
  `acct_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账户ID',
  `category_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类ID',
  `game_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏代码',
  `ticket_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '票据时间',
  `bet_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注IP',
  `bet_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `win_loss` decimal(20, 2) NULL DEFAULT NULL COMMENT '输赢',
  `result` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结果',
  `lucky_draw_id` bigint(20) NULL DEFAULT NULL COMMENT '幸运抽奖ID',
  `completed` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否完成',
  `round_id` bigint(20) NULL DEFAULT NULL COMMENT '轮次ID',
  `sequence` int(11) NULL DEFAULT NULL COMMENT '序列',
  `channel` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道',
  `balance` decimal(20, 2) NULL DEFAULT NULL COMMENT '余额',
  `jp_win` decimal(20, 2) NULL DEFAULT NULL COMMENT 'JP赢取',
  `reference_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参考ID',
  `game_feature` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏特性',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ticket_id`(`ticket_id` ASC) USING BTREE,
  INDEX `idx_acct_id`(`acct_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_game_code`(`game_code` ASC) USING BTREE,
  INDEX `idx_ticket_time`(`ticket_time` ASC) USING BTREE,
  INDEX `idx_round_id`(`round_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9618 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Spade投注记录原始表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_fc_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_fc_bet_raw_log`;
CREATE TABLE `tb_fc_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `record_id` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏记录编号(唯一码)',
  `account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家账号',
  `game_id` int(11) NULL DEFAULT NULL COMMENT '游戏编号',
  `gametype` int(11) NULL DEFAULT NULL COMMENT '游戏类型',
  `bet` decimal(20, 6) NULL DEFAULT NULL COMMENT '下注点数',
  `winlose` decimal(18, 6) NULL DEFAULT NULL COMMENT '净输赢点数',
  `prize` decimal(18, 6) NULL DEFAULT NULL COMMENT '赢分点数',
  `refund` decimal(18, 6) NULL DEFAULT NULL COMMENT '退还金额',
  `valid_bet` decimal(18, 6) NULL DEFAULT NULL COMMENT '有效投注',
  `commission` decimal(18, 6) NULL DEFAULT NULL COMMENT '抽水金额',
  `jpmode` int(11) NULL DEFAULT NULL COMMENT '彩金模式',
  `in_game_jpmode` int(11) NULL DEFAULT NULL COMMENT '游戏内彩金模式',
  `jppoints` decimal(18, 6) NULL DEFAULT NULL COMMENT '彩金点数',
  `jptax` decimal(18, 6) NULL DEFAULT NULL COMMENT '彩金抽水',
  `in_game_jptax` decimal(18, 6) NULL DEFAULT NULL COMMENT '游戏内彩金贡献',
  `in_game_jppoints` decimal(18, 6) NULL DEFAULT NULL COMMENT '游戏内中奖彩金',
  `before` decimal(18, 6) NULL DEFAULT NULL COMMENT '下注前点数',
  `after` decimal(18, 6) NULL DEFAULT NULL COMMENT '下注后点数',
  `bdate` datetime NULL DEFAULT NULL COMMENT '下注时间',
  `is_buy_feature` tinyint(1) NULL DEFAULT NULL COMMENT '是否购买免费游戏',
  `game_mode` int(11) NULL DEFAULT NULL COMMENT '红利/免费游戏类型',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_fc_bet_raw_log_record_id_IDX`(`record_id` ASC) USING BTREE,
  INDEX `idx_bdate`(`bdate` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 198349 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'FC原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_funta_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_funta_bet_raw_log`;
CREATE TABLE `tb_funta_bet_raw_log`  (
  `id` bigint(20) NOT NULL COMMENT '注单编号，唯一值',
  `bet_at` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '下注时间，ISO 8601时间格式',
  `modified_at` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '修改时间，ISO 8601时间格式',
  `payoff_at` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '结算时间，ISO 8601时间格式',
  `lobby_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏大厅编号，参考游戏大厅清单',
  `game_id` int(11) NOT NULL COMMENT '游戏编号',
  `game_group_id` int(11) NOT NULL COMMENT '游戏分组编号',
  `username` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账号，长度3-20',
  `bet_amount` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '下注金额',
  `payoff` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '派彩金额',
  `profit` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '损益（派彩金额 - 下注金额）',
  `balance` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '余额，会员当下的余额',
  `commission` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '退水金额，给玩家的回馈金',
  `commissionable` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '有效投注总和（下注金额 - 退水金额），若注单注销则为0',
  `currency` int(11) NOT NULL COMMENT '币别代码，参考支援币别',
  `device` tinyint(4) NOT NULL COMMENT '下注来源：0-网页, 1-Android, 2-iOS, 3-mweb',
  `device_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源版本',
  `result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单结果，参考注单结果代码',
  `feature_game` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特色游戏：BG-BonusGame奖励游戏, FG-FreeGame免费游戏, JP-Jackpot游戏大奖',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏类型：slots, table, fishing, arcade等',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id_idx`(`id` ASC) USING BTREE,
  INDEX `idx_bet_at`(`bet_at` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'FunTa原始注单记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_ga28_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_ga28_bet_raw_log`;
CREATE TABLE `tb_ga28_bet_raw_log`  (
  `id` bigint(32) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `sid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员注册ID',
  `created_date_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注册创建时间',
  `modified_date_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注册更新时间',
  `settled_date_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注册结算时间',
  `arena_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场地 Code',
  `match_day_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当日赛事号',
  `fight_number` int(20) NULL DEFAULT NULL COMMENT '赛事局号',
  `selection` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员下投注项',
  `odds` decimal(10, 4) NULL DEFAULT NULL COMMENT '会员赔率',
  `bet_amount` decimal(10, 4) NULL DEFAULT NULL COMMENT '下注金额',
  `valid_stake` decimal(10, 4) NULL DEFAULT NULL COMMENT '有效下注金额',
  `ticket_amount` decimal(10, 4) NULL DEFAULT NULL COMMENT '注金额',
  `ante_amount` decimal(10, 4) NULL DEFAULT NULL COMMENT '奖金费',
  `status` int(32) NULL DEFAULT NULL COMMENT '注单状态：0-注单确定 1-结算中 2-结算了不过在等派彩 3-结算了不过派彩正在进行中 4-注单结算了 5-取消不过在等派彩 6-取消了不过派彩正在进行中 7-注单取消 8-注单作废中 9-注单作废了 10-重新结算不过在等派彩 11-重新结算不过派彩正在进行中 12-重新取消单，正在等派彩 13-重新取消单了，派彩正在处理中',
  `result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单结果：win-注单已结算为赢 loss-注单已结算为输 draw-注单已结算为打和',
  `fight_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赛事结果',
  `member_ref_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员ID',
  `account_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Partner Account ID',
  `currency_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币',
  `win_loss_amount` decimal(10, 4) NULL DEFAULT NULL COMMENT '派彩金额',
  `odds_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率类型',
  `ip_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'User agent',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(32) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(32) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `sid_unique`(`sid` ASC) USING BTREE,
  INDEX `idx_created_date_time`(`created_date_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 208507 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'GA28原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game
-- ----------------------------
DROP TABLE IF EXISTS `tb_game`;
CREATE TABLE `tb_game`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏标识',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏厂商code',
  `gp_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商名称',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆code',
  `venue_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属场馆名称',
  `category_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏分类/品类Code',
  `remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `maintain_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `maintain_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护备注，关联remark_type',
  `source_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `source_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源备注',
  `source_maintain_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `source_maintain_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源维护备注',
  `status` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '游戏列表-游戏状态： 启用-- ENABLED；停用--DISABLED',
  `maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAIN' COMMENT '游戏列表-维护状态：维护--MAINTAIN；不维护--NOT_MAINTAIN',
  `source_status` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '游戏源--游戏状态： 启用-- ENABLED；停用--DISABLED',
  `source_maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAIN' COMMENT '游戏源--维护状态：维护--MAINTAIN；不维护--NOT_MAINTAIN',
  `line_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线路状态：ENABLED-正常；DISABLED-异常',
  `status_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护/停用/异常时间 展示',
  `maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间起始',
  `maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间结束',
  `disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '停止时间',
  `maintain_trigger_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录触发维护状态时，上一个使用状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '特殊参数（json格式，用于game_id匹配等）',
  `tag_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签id',
  `tag_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签名称',
  `name_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '名称多语言json',
  `landscape_forced` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'PORTRAIT' COMMENT '游戏横竖屏：PORTRAIT-竖屏,LANDSCAPE-横屏,BOTH-都支持',
  `hot` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '(\"HOT\", \"热门\"),(\"NOT_HOT\", \"非热门\");',
  `platform` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ALL' COMMENT '支持终端:WEB-网页端，H5-h5端，ALL-都支持',
  `rebate` tinyint(1) UNSIGNED ZEROFILL NOT NULL DEFAULT 1 COMMENT '是否返水 0-不返水 1-返水',
  `sort` int(11) NOT NULL DEFAULT 9999 COMMENT '游戏排序值',
  `volatility` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '波动性 NONE-无 ',
  `rtp` decimal(20, 2) NULL DEFAULT NULL COMMENT '返奖率(RTP)',
  `max_multiplier` int(11) NULL DEFAULT NULL COMMENT '最大倍数',
  `number_game_line` int(11) NULL DEFAULT NULL COMMENT '游戏线数',
  `background_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '背景图',
  `video` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '视频',
  `introducing_copywriting` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '介绍文案',
  `custom_icons` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自定义图标',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `show_status` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `site_status` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `source_disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏源 --停止时间',
  `source_maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏源 --维护时间结束',
  `source_maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏源 --维护时间起始',
  `source_status_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源 --维护/停用/异常时间 展',
  `super_maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAI' COMMENT '上级-维护状态：维护--MAINTAIN；不维护--NOT_MAINTAI',
  `super_status` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '上级-- 游戏开关  启用-- ENABLED；停用--DISABLED',
  `is_use_sys_icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT '是否使用系统图标 N-使用自定义图标，Y-使用系统图标',
  `min_transfer_amount` decimal(18, 2) NOT NULL DEFAULT 1.00 COMMENT '最低转入金额，默认：1',
  `max_transfer_amount` decimal(18, 2) NULL DEFAULT 10000.00 COMMENT '最高转入金额(转入游戏厂商限制，默认：10000)',
  `c_show_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'DISABLED' COMMENT 'C端使用字段， 启用-- ENABLED；停用--DISABLED； 站点维护--MAINTAIN； 源维护--SOURCE_MAINTAIN；',
  `hot_sort` int(11) NOT NULL DEFAULT 9999 COMMENT '热门游戏排序',
  `trial_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试玩地址',
  `trial_status` char(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试玩状态  ON-开启，OFF-关闭， NONE-不存在',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `codeVenuecodeIndex`(`code` ASC, `venue_code` ASC) USING BTREE,
  INDEX `idx_game_hot_status_category_sort`(`category_code` ASC, `c_show_status` ASC, `hot` ASC, `sort` ASC, `update_time` ASC) USING BTREE,
  INDEX `idx_category_cshow_hot_sort`(`category_code` ASC, `c_show_status` ASC, `hot` ASC, `sort` ASC) USING BTREE,
  INDEX `idx_category_cshow_venue_sort`(`category_code` ASC, `c_show_status` ASC, `venue_code` ASC, `sort` ASC) USING BTREE,
  INDEX `idx_category_cshow_gp_sort`(`category_code` ASC, `c_show_status` ASC, `gp_code` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15119 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game5g_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_game5g_bet_raw_log`;
CREATE TABLE `tb_game5g_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `start_date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单日期，格式yyyy-MM-dd',
  `account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家账号',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '由5G生成的单号',
  `gid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主游戏ID（最大长度64字元）',
  `s_tm` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间，格式yyyy-MM-dd HH:mm:ss',
  `tm` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束时间，格式HH:mm:ss',
  `bet` bigint(20) NULL DEFAULT NULL COMMENT '押注（以Cent为单位）',
  `dm` bigint(20) NULL DEFAULT NULL COMMENT '比率（以Cent为单位）',
  `win` bigint(20) NULL DEFAULT NULL COMMENT '总赢分（以Cent为单位，包含免费游戏、比倍游戏）',
  `rd` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏回合其他信息（最大长度255字元）',
  `bn` bigint(20) NULL DEFAULT NULL COMMENT '免费游戏赢分（以Cent为单位）',
  `gb` bigint(20) NULL DEFAULT NULL COMMENT '比倍遊戲赢分（以Cent为单位）',
  `jp` bigint(20) NULL DEFAULT NULL COMMENT 'JACKPOT赢分（以Cent为单位）',
  `bet_gt` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类型',
  `jc` decimal(15, 2) NULL DEFAULT NULL COMMENT '彩金贡献金（以Cent为单位，四舍五入至小数第二位）',
  `offln` smallint(6) NULL DEFAULT NULL COMMENT '玩家断线时由系统自动完成(0=否,1=是)',
  `bd` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '免费游戏数据（JSON数组）',
  `jd` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '彩金数据（JSON数组）',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始响应JSON',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sn`(`sn` ASC) USING BTREE,
  INDEX `idx_created_s_tm`(`s_tm` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 89107 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '5G原始注单记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_access_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_access_log`;
CREATE TABLE `tb_game_access_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '用户ID',
  `account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户账户',
  `game_account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户游戏账户',
  `gp_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏提供商代码',
  `game_id` bigint(20) NOT NULL COMMENT '游戏主键ID',
  `game_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏code',
  `start_time` bigint(20) NOT NULL COMMENT '游戏开始时间（Unix时间戳）',
  `end_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏结束时间（Unix时间戳）',
  `stay_duration` bigint(20) NULL DEFAULT NULL COMMENT '停留时长（秒）',
  `platform` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台类型（如：Web、iOS、Android）',
  `ip_address` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员IP地址',
  `browser` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户浏览器信息',
  `create_time` bigint(20) NOT NULL COMMENT '记录创建时间（Unix时间戳）',
  `update_time` bigint(20) NOT NULL COMMENT '记录更新时间（Unix时间戳）',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `venue_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏场馆code',
  `status` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员访问游戏状态：IN-进入游戏，OUT-离开游戏',
  `venue_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏场馆名称',
  `in_request_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '启动游戏访问追踪requestId',
  `out_request_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退出游戏访问追踪requestId',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_uid_gameid_status_createtime`(`uid` ASC, `game_id` ASC, `status` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41996 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员游戏访问记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_account_binding
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_account_binding`;
CREATE TABLE `tb_game_account_binding`  (
  `id` int(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户名称',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户状态',
  `uid` bigint(20) NOT NULL COMMENT '用户ID',
  `game_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏账户',
  `password` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码',
  `salt` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盐值',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间，毫秒级时间戳',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间，毫秒级时间戳',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `gp_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商code',
  `gp_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商名称',
  `u_game_token` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员游戏厂商token（有些厂商游戏token我们自己维护）',
  `currency` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员绑定的币种',
  `lang` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员绑定的语种（首次访问游戏厂商绑定语种）',
  `last_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员最近一次访问游戏厂商IP',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `gaccountGpcodeIndex`(`game_account` ASC, `gp_code` ASC) USING BTREE,
  UNIQUE INDEX `gameuidgpcode`(`uid` ASC, `gp_code` ASC) USING BTREE,
  INDEX `idx_account_gpcode`(`account` ASC, `gp_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21378 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员游戏账户关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_bak
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_bak`;
CREATE TABLE `tb_game_bak`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏标识',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏厂商code',
  `gp_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商名称',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆code',
  `venue_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属场馆名称',
  `category_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏分类/品类Code',
  `remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `maintain_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `maintain_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护备注，关联remark_type',
  `source_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `source_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源备注',
  `source_maintain_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `source_maintain_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源维护备注',
  `status` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '游戏列表-游戏状态： 启用-- ENABLED；停用--DISABLED',
  `maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAIN' COMMENT '游戏列表-维护状态：维护--MAINTAIN；不维护--NOT_MAINTAIN',
  `source_status` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '游戏源--游戏状态： 启用-- ENABLED；停用--DISABLED',
  `source_maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAIN' COMMENT '游戏源--维护状态：维护--MAINTAIN；不维护--NOT_MAINTAIN',
  `line_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线路状态：ENABLED-正常；DISABLED-异常',
  `status_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护/停用/异常时间 展示',
  `maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间起始',
  `maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间结束',
  `disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '停止时间',
  `maintain_trigger_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录触发维护状态时，上一个使用状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '特殊参数（json格式，用于game_id匹配等）',
  `tag_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签id',
  `tag_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签名称',
  `name_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '名称多语言json',
  `landscape_forced` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'PORTRAIT' COMMENT '游戏横竖屏：PORTRAIT-竖屏,LANDSCAPE-横屏,BOTH-都支持',
  `hot` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '(\"HOT\", \"热门\"),(\"NOT_HOT\", \"非热门\");',
  `platform` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ALL' COMMENT '支持终端:WEB-网页端，H5-h5端，ALL-都支持',
  `rebate` tinyint(1) UNSIGNED ZEROFILL NOT NULL DEFAULT 1 COMMENT '是否返水 0-不返水 1-返水',
  `sort` int(11) NULL DEFAULT NULL COMMENT '游戏排序值',
  `volatility` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '波动性 NONE-无 ',
  `rtp` decimal(20, 2) NULL DEFAULT NULL COMMENT '返奖率(RTP)',
  `max_multiplier` int(11) NULL DEFAULT NULL COMMENT '最大倍数',
  `number_game_line` int(11) NULL DEFAULT NULL COMMENT '游戏线数',
  `background_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '背景图',
  `video` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '视频',
  `introducing_copywriting` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '介绍文案',
  `custom_icons` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自定义图标',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `show_status` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `site_status` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `source_disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏源 --停止时间',
  `source_maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏源 --维护时间结束',
  `source_maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏源 --维护时间起始',
  `source_status_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏源 --维护/停用/异常时间 展',
  `super_maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAI' COMMENT '上级-维护状态：维护--MAINTAIN；不维护--NOT_MAINTAI',
  `super_status` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '上级-- 游戏开关  启用-- ENABLED；停用--DISABLED',
  `is_use_sys_icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT '是否使用系统图标 N-使用自定义图标，Y-使用系统图标',
  `min_transfer_amount` decimal(18, 2) NOT NULL DEFAULT 1.00 COMMENT '最低转入金额，默认：1',
  `max_transfer_amount` decimal(18, 2) NULL DEFAULT 10000.00 COMMENT '最高转入金额(转入游戏厂商限制，默认：10000)',
  `c_show_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'DISABLED' COMMENT 'C端使用字段， 启用-- ENABLED；停用--DISABLED； 站点维护--MAINTAIN； 源维护--SOURCE_MAINTAIN；',
  `hot_sort` int(11) NULL DEFAULT NULL COMMENT '热门游戏排序',
  `trial_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试玩地址',
  `trial_status` char(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试玩状态  ON-开启，OFF-关闭， NONE-不存在',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `codeVenuecodeIndex`(`code` ASC, `venue_code` ASC) USING BTREE,
  INDEX `idx_game_hot_status_category_sort`(`category_code` ASC, `c_show_status` ASC, `hot` ASC, `sort` ASC, `update_time` ASC) USING BTREE,
  INDEX `idx_category_cshow_hot_sort`(`category_code` ASC, `c_show_status` ASC, `hot` ASC, `sort` ASC) USING BTREE,
  INDEX `idx_category_cshow_venue_sort`(`category_code` ASC, `c_show_status` ASC, `venue_code` ASC, `sort` ASC) USING BTREE,
  INDEX `idx_category_cshow_gp_sort`(`category_code` ASC, `c_show_status` ASC, `gp_code` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14021 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_bet_order_std
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_bet_order_std`;
CREATE TABLE `tb_game_bet_order_std`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_time` datetime NOT NULL COMMENT '下注时间（分区）',
  `system_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '系统注单号',
  `uid` bigint(20) NOT NULL COMMENT '会员uid',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员账户',
  `game_account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员游戏账户',
  `currency` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '当前币种',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商code',
  `category_code` tinyint(3) NOT NULL DEFAULT 0 COMMENT '品类 1:SPORTS-体育 2:SLOT-老虎机 3:LIVE-真人 4:POKER-棋牌 5:FISHING-捕鱼,6:ESPORTS-电竞,7:LOTTERY-彩票,8:ANIMAL-斗鸡',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆code',
  `game_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏主键ID',
  `game_name` varchar(48) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `is_exception` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'N' COMMENT '是否异常注单： Y-是，N-否（通用）',
  `bet_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '三方注单号',
  `order_status` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '注单订单状态: 10-未结算,11-未结算-已确认,12-未结算-无兑现,13-未结算-取消兑现,20-已结算-已结算,21-已结算-已重新结算,22-已结算-兑现售出,23-已结算-已确认,30-已取消-划单,31-已取消-已结算,32-已取消- 未结算',
  `win_lose_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '输赢状态',
  `bet_time` bigint(20) NOT NULL COMMENT '下注时间',
  `settle_time` bigint(20) NULL DEFAULT NULL COMMENT '注单结算时间（多单取最后一单）',
  `bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '投注金额',
  `gp_valid_bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '厂商原有效投注金额',
  `calc_valid_bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '二次计算有效投注金额',
  `win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '中奖金额（最小为0）',
  `payout_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '金额',
  `multiple` decimal(18, 4) NULL DEFAULT NULL COMMENT '倍数',
  `win_lose_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '玩家输赢金额/净输赢（有负数）',
  `max_win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '预计最大可赢金额（未结算）',
  `bet_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'SINGLE' COMMENT '投注类型: SINGLE-普通注单, PARLAY-普通串关, MIX_PARLAY-混合串关',
  `bet_platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注终端（通用）: WEB-网页, H5-移动端, APP-应用程序, NONE-未知',
  `sub_order_count` int(11) NULL DEFAULT 0 COMMENT '子注单数量',
  `bet_count` int(11) NULL DEFAULT NULL COMMENT '投注数量',
  `jackpot` bigint(20) NULL DEFAULT NULL COMMENT '奖池金额',
  `jackpot_contribution` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖池返还率贡献额',
  `round_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '局号/期号（真人，棋牌，斗鸡，彩票等）',
  `table_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桌号（真人，棋牌等）',
  `follow_bet` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '追号：Y-是,N-否（彩票）',
  `play_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法：大枚举',
  `balance_before` decimal(18, 4) NULL DEFAULT NULL COMMENT '投注前余额',
  `balance_after` decimal(18, 4) NULL DEFAULT NULL COMMENT '投注后余额',
  `donate` decimal(18, 4) NULL DEFAULT NULL COMMENT '打赏金额（真人）',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新时间',
  `bet_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '串关名称',
  `odds` decimal(18, 4) NULL DEFAULT NULL COMMENT '赔率(体育电竞彩票)',
  `total_settle_odds` decimal(18, 4) NULL DEFAULT NULL COMMENT '结算总赔率',
  `match_period` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '半场全场',
  `betting_options` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注选项',
  `exclude_valid_bet` tinyint(4) NULL DEFAULT 0 COMMENT '不计算有效投注标识：0=否，1=是',
  PRIMARY KEY (`uid`, `order_time`, `id`) USING BTREE,
  UNIQUE INDEX `idx_bet_order_no`(`bet_order_no` ASC, `gp_code` ASC, `uid` ASC, `order_time` ASC) USING BTREE,
  INDEX `idx_categorycode_ordertime`(`category_code` ASC, `order_time` ASC) USING BTREE,
  INDEX `idx_autoinc`(`id` ASC) USING BTREE,
  INDEX `idx_bettype_categorycode_ordertime_account`(`account` ASC, `category_code` ASC, `bet_type` ASC, `order_time` ASC) USING BTREE,
  INDEX `idx_categorycode_ordertime_account`(`account` ASC, `category_code` ASC, `order_time` ASC) USING BTREE,
  INDEX `idx_uid_ordertime_desc_status`(`uid` ASC, `order_time` ASC, `order_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3834486469 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'COLUMNAR=1 游戏标准注单' ROW_FORMAT = Dynamic PARTITION BY RANGE COLUMNS (`order_time`;INTERVAL(DAY, 1))
PARTITIONS 53
SUBPARTITION BY HASH (`uid`)
