-- ----------------------------
-- Table structure for tb_game_bet_order_sub
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_bet_order_sub`;
CREATE TABLE `tb_game_bet_order_sub`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_time` datetime NOT NULL COMMENT '下注时间（分区）',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆code',
  `game_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏主键ID',
  `is_exception` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'N' COMMENT '是否异常注单： Y-是，N-否（通用）',
  `bet_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '三方注单号',
  `parent_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '母注单号',
  `order_status` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '注单订单状态: 10-未结算,11-未结算-已确认,12-未结算-无兑现,13-未结算-取消兑现,20-已结算-已结算,21-已结算-已重新结算,22-已结算-兑现售出,23-已结算-已确认,30-已取消-划单,31-已取消-已结算,32-已取消-未结算',
  `win_lose_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单输赢状态: WIN-赢, LOSS-输, TIE-和, WIN_HALF-赢半, LOSE_HALF-输半, NONE-无',
  `bet_time` bigint(20) NOT NULL COMMENT '下注时间',
  `settle_time` bigint(20) NULL DEFAULT NULL COMMENT '注单结算时间（多单取最后一单）',
  `bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '投注金额',
  `gp_valid_bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '厂商原有效投注金额',
  `win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '玩家赢金额/派彩额（无负数）',
  `win_lose_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '玩家输赢金额/净输赢（有负数）',
  `max_win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '预计最大可赢金额（未结算）',
  `jackpot` bigint(20) NULL DEFAULT NULL COMMENT '奖池金额',
  `jackpot_contribution` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖池返还率贡献额',
  `bet_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注实际内容',
  `result_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开奖结果内容',
  `play_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法：大枚举',
  `game_wallet` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏钱包',
  `odds_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率类型（别名盘口，体育）: HONG_KONG-香港盘, EUROPEAN-欧洲盘, MALAY-马来盘, INDONESIAN-印尼盘',
  `odds` decimal(18, 4) NULL DEFAULT NULL COMMENT '赔率(投注时的赔率,三位小数)',
  `settle_odds` decimal(18, 4) NULL DEFAULT NULL COMMENT '结算赔率(三位小数)',
  `odds_increase_status` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率增值状态: NOT_STARTED-未启动, STARTED-已启动',
  `mix_parlay_after_add_odds` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '混合过关投注增值后的赔率（体育）',
  `cash_success_time` bigint(20) NULL DEFAULT NULL COMMENT '兑现成功时间(若投注没被兑现 = none)',
  `repurchase_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '兑现回购金额（无为null）',
  `market` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市场（体育）: MORNING-早盘, TODAY-今日, ROLLING_BALL-滚球, NONE-无',
  `sport_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体育项目名称',
  `league_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联赛名称（体育）',
  `match_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '比赛名称（体育）',
  `home_team_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主队名称（体育）',
  `away_team_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客队名称（体育）',
  `popular_teams` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热门队伍（体育）: H-主队是热门球队, A-客队是热门球队, 若投注类型是优胜冠军或连串过关 = null',
  `match_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赛事ID',
  `match_period` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '半场全场（体育）: FIRST_HALF-上半场, SECOND_HALF-下半场, FULL-全场, 若投注类型是优胜冠军 = null',
  `match_time_start` bigint(20) NULL DEFAULT NULL COMMENT '比赛时间（体育）',
  `match_time_end` bigint(20) NULL DEFAULT NULL COMMENT '比赛时间（体育）',
  `handicap` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '让球盘（体育）:投注选项是让球盘,\"-\" 表示客队让分, \"+\"表示主队让分,若投注类型是优胜冠军 = null',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注/附加信息',
  `is_betting_port_cancelled` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注口是否已取消: Y-是的，N-否',
  `betting_port_cancelled_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注口取消类型: NOT_CANCELLED-尚未取消, EVENT_CANCELLED-赛事被取消, BETS_CANCELLED-投注被取消',
  `betting_port_cancelled_reasons` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注口取消原因',
  `lottery_type_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '彩种组(彩票)',
  `exceed_win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '超额中奖金额(彩票)',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `bet_order_no_idx`(`bet_order_no` ASC) USING BTREE,
  INDEX `parent_order_no_idx`(`parent_order_no` ASC) USING BTREE,
  INDEX `create_time_idx`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 613964 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏标准子注单（体育、电竞）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_bet_raw_order
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_bet_raw_order`;
CREATE TABLE `tb_game_bet_raw_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商code',
  `bet_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '三方注单号',
  `flag` tinyint(4) NOT NULL COMMENT '变更标记：0-NONE,1-INSERT,2-UPDATE',
  `raw_order` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始注单',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`gp_code` ASC, `bet_order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81143 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '历史Job游戏原始注单（只保留3天即可）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_game_category
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_category`;
CREATE TABLE `tb_game_category`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类代码（唯一标识）',
  `sort` int(11) NULL DEFAULT NULL COMMENT '排序',
  `icon_url` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图标URL',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳）',
  `name_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分类多语言json',
  `image_uri` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '自定义图片',
  `image_uri_default` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '系统图片',
  `use_image_uri` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用自定义图片；1是，0不是',
  `is_web_zone` tinyint(1) NULL DEFAULT NULL COMMENT '是否是zone',
  `is_enabled` tinyint(1) NULL DEFAULT NULL COMMENT '是否启用',
  `h5_image_uri` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'H5自定义图片',
  `h5_image_uri_default` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'H5系统图片',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏分类表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_client_tag
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_client_tag`;
CREATE TABLE `tb_game_client_tag`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tag_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签名称',
  `tag_color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签颜色',
  `tag_desc` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签描述',
  `apply_object` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应用对象',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态: ENABLED ;DISABLED',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳）',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签类型: 通用标签;游戏入口标签;活动封面标签',
  `relation_config_id` bigint(20) NULL DEFAULT NULL COMMENT '关系配置ID',
  `apply_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '應用id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 236 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户端标签配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_currency_kind
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_currency_kind`;
CREATE TABLE `tb_game_currency_kind`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `currency_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种code',
  `status` smallint(6) NULL DEFAULT NULL COMMENT '状态:1-2-',
  `currency_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种名称',
  `currency_type` smallint(6) NULL DEFAULT NULL COMMENT '1法币,2虚拟币',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏币种' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_enter_record
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_enter_record`;
CREATE TABLE `tb_game_enter_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `user_id` int(11) NOT NULL COMMENT '会员主键ID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户账户',
  `game_id` bigint(20) NOT NULL COMMENT '游戏主键ID',
  `game_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏code',
  `layout` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'BOTH' COMMENT '游戏横竖屏：PORTRAIT-竖屏,LANDSCAPE-横屏,BOTH-都支持',
  `gp_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商code',
  `gp_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类code',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆code',
  `venue_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆名称',
  `min_transfer_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '最低转入金额',
  `max_transfer_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '最高转入金额',
  `direction` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方向: IN-进入游戏，OUT-离开游戏',
  `enter_time` bigint(20) NOT NULL COMMENT '游戏进入时间',
  `exit_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏退出时间',
  `enter_order_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进入游戏订单号',
  `exit_order_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退出游戏订单号',
  `game_account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户游戏账户',
  `game_password` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户游戏密码',
  `game_token` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户游戏账户',
  `site_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '站点',
  `site_lang` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '语言',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种',
  `user_lang` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '语言',
  `user_plat` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台类型（如：Web、iOS、Android）',
  `user_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员IP地址',
  `user_agent` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '浏览器',
  `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请求ID',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_uid_game_id_dir`(`uid` ASC, `game_id` ASC, `direction` ASC) USING BTREE,
  INDEX `idx_direction_entertime`(`direction` ASC, `enter_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43362 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏进入记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_member_wallet
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_member_wallet`;
CREATE TABLE `tb_game_member_wallet`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员账号',
  `balance` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '钱包余额',
  `flag` smallint(6) NOT NULL DEFAULT 0 COMMENT '标志',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_uid`(`uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏会员钱包' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_game_member_wallet_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_member_wallet_log`;
CREATE TABLE `tb_game_member_wallet_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_time` datetime NULL DEFAULT NULL COMMENT '订单时间',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员账号',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `related_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联订单号',
  `provider_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商编码',
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '品类编码',
  `change_subject` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账变科目：TRANSFER,GAME',
  `change_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账变类型：TRANSFER_IN,TRANSFER_OUT,GAME_BET,GAME_PAYOUT,GAME_REFUND',
  `balance_change` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '变化余额',
  `balance_before` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '变化前余额',
  `balance_after` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '变化后余额',
  `flag` smallint(6) NOT NULL DEFAULT 0 COMMENT '标志',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_uid_order_no`(`uid` ASC, `order_no` ASC) USING BTREE,
  INDEX `idx_uid_provider`(`uid` ASC, `flag` ASC, `provider_code` ASC, `category_code` ASC) USING BTREE,
  INDEX `idx_order_time_change_type`(`order_time` ASC, `change_subject` ASC, `change_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8889 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏会员钱包账变日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_game_online_record
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_online_record`;
CREATE TABLE `tb_game_online_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '用户ID',
  `account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户账户',
  `game_account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户游戏账户',
  `gp_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏提供商代码',
  `game_id` bigint(20) NOT NULL COMMENT '游戏主键ID',
  `game_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏code',
  `start_time` bigint(20) NOT NULL COMMENT '游戏开始时间（Unix时间戳）',
  `end_time` bigint(20) NULL DEFAULT NULL COMMENT '游戏结束时间（Unix时间戳）',
  `stay_duration` bigint(20) NULL DEFAULT NULL COMMENT '停留时长（秒）',
  `platform` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台类型（如：Web、iOS、Android）',
  `ip_address` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员IP地址',
  `browser` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户浏览器信息',
  `create_time` bigint(20) NOT NULL COMMENT '记录创建时间（Unix时间戳）',
  `update_time` bigint(20) NOT NULL COMMENT '记录更新时间（Unix时间戳）',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `venue_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏场馆code',
  `status` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员访问游戏状态：IN-进入游戏，OUT-离开游戏',
  `venue_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏场馆名称',
  `in_request_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '启动游戏访问追踪requestId',
  `out_request_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退出游戏访问追踪requestId',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏在线记录' ROW_FORMAT = DYNAMIC;

