) ENGINE = InnoDB AUTO_INCREMENT = 111 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏供应商' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_rebate_claim_record
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_rebate_claim_record`;
CREATE TABLE `tb_game_rebate_claim_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员账号',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '返水订单号',
  `rebate_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '返水类型：REAL_TIME-实时,COMPENSATION-补偿',
  `rebate_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '返水金额',
  `claim_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '领取方式：MANUAL-手动,AUTOMATIC-自动',
  `audit_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '：审批状态：PENDING-待审核，APPROVED-通过, REJECTED-拒绝',
  `time_min` bigint(20) NOT NULL COMMENT '最小时间',
  `time_max` bigint(20) NOT NULL COMMENT '最大时间',
  `acked` smallint(6) NOT NULL DEFAULT 0 COMMENT '确认状态',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_uid_time_min`(`uid` ASC, `time_min` ASC, `rebate_type` ASC) USING BTREE,
  UNIQUE INDEX `uk_uid_time_max`(`uid` ASC, `time_max` ASC, `rebate_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1644 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏返水领取记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_rebate_config
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_rebate_config`;
CREATE TABLE `tb_game_rebate_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `level` int(11) NOT NULL COMMENT '等级',
  `valid_bet_amount` decimal(18, 2) UNSIGNED NOT NULL COMMENT '有效投注',
  `ratio_slot` decimal(8, 4) UNSIGNED NOT NULL COMMENT '老虎机比例',
  `ratio_fishing` decimal(8, 4) UNSIGNED NOT NULL COMMENT '捕鱼比例',
  `ratio_live` decimal(8, 4) UNSIGNED NOT NULL COMMENT '真人比例',
  `ratio_poker` decimal(8, 4) UNSIGNED NOT NULL COMMENT '棋牌比例',
  `ratio_lottery` decimal(8, 4) UNSIGNED NOT NULL COMMENT '彩票比例',
  `ratio_animal` decimal(8, 4) UNSIGNED NOT NULL COMMENT '斗鸡比例',
  `ratio_sports` decimal(8, 4) UNSIGNED NOT NULL COMMENT '体育比例',
  `ratio_esports` decimal(8, 4) UNSIGNED NOT NULL COMMENT '电竞比例',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_level`(`level` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 164 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏返水配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_game_rebate_issue_record
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_rebate_issue_record`;
CREATE TABLE `tb_game_rebate_issue_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员账号',
  `system_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '系统注单号',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏厂商code',
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类code',
  `game_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏主键ID',
  `bet_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '三方注单号',
  `valid_bet_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '有效投注',
  `rebate_ratio` decimal(8, 4) NULL DEFAULT NULL COMMENT '返水比例',
  `rebate_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '返水金额',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bet_order_no`(`gp_code` ASC, `bet_order_no` ASC) USING BTREE,
  INDEX `idx_uid_category`(`uid` ASC, `category_code` ASC) USING BTREE,
  INDEX `idx_system_no`(`system_no` ASC) USING BTREE,
  INDEX `idx_uid_createtime_account_rebateamount`(`uid` ASC, `create_time` ASC, `account` ASC, `rebate_amount` ASC) USING BTREE,
  INDEX `idx_createtime_uid`(`create_time` ASC, `uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4833969 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏返水发放记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_game_relation
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_relation`;
CREATE TABLE `tb_game_relation`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `game_id` bigint(20) NOT NULL COMMENT '游戏ID',
  `lang` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '语种代码',
  `relation_config_id` bigint(20) NOT NULL COMMENT '关系配置ID',
  `config_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置类型',
  `sort_order` int(11) NULL DEFAULT NULL COMMENT '排序（自定义排序，混合排序）',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳）',
  `game_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `gpk_id` bigint(20) NOT NULL COMMENT '场馆id',
  `gpk_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆名称',
  `status` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态：T- 草稿状态; C- 完成状态',
  `venue_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆code',
  `category_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏分类代码',
  `game_sort_order` int(11) NULL DEFAULT NULL COMMENT '游戏排序号（原始排序）',
  `gp_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商code',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tb_game_relation`(`game_id` ASC, `lang` ASC, `relation_config_id` ASC) USING BTREE,
  INDEX `idx_game_relation_category_lang_status`(`relation_config_id` ASC, `lang` ASC, `category_code` ASC, `status` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_game_id`(`game_id` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_sort_order`(`sort_order` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_config_id`(`relation_config_id` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_lang`(`lang` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12373 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_relation_config
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_relation_config`;
CREATE TABLE `tb_game_relation_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置名称',
  `config_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置类型',
  `is_enabled` tinyint(1) NULL DEFAULT NULL COMMENT '是否启用',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '父配置ID',
  `sort_order` int(11) NULL DEFAULT NULL COMMENT '排序',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态：T-预生成状态；C-已完成状态',
  `redirect_page` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跳转页面',
  `image_uri` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片URI',
  `image_uri_default` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '默认图片URI',
  `use_image_uri` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用自定义图片: true-使用品类图标image_uri, false 或 null -默认图片image_uri_default',
  `is_web_zone` tinyint(4) NULL DEFAULT NULL COMMENT '是否为WEB专区',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tb_game_relation_config_enabled`(`is_enabled` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_config_type`(`config_type` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_config_parent_id`(`parent_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2026021200000003 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '关系配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_relation_config_i18n
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_relation_config_i18n`;
CREATE TABLE `tb_game_relation_config_i18n`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `relation_config_id` bigint(20) NOT NULL COMMENT '关系配置ID',
  `lang` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '语种代码 如: zh_CN, en_US, ja_JP',
  `alias_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '别名',
  `image_uri` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片URI',
  `relation_strategy` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关系策略配置（Json字符串). RAW-原始的;MIXED-混合的;CUSTOM-自定义的;SMART-智能的。 \r\n例如：relationStrategy:{\"setting\":\"CUSTOM\"}',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳）',
  `color` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `is_smart_sort` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否智能排序，ture-游戏入口(智能排序), false-游戏入口(自定义排序)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tb_game_relation_config_i18n_lang`(`lang` ASC) USING BTREE,
  INDEX `idx_tb_game_relation_config_i18n_config_id`(`relation_config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1075 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '关系配置多语种表' ROW_FORMAT = DYNAMIC;

