  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳）',
  `relation_config_id` bigint(20) NOT NULL COMMENT '关系配置ID',
  `type` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'GAME_RECOMMEND游戲推薦入口配置 ;\r\nJUMP_PAGE 跳轉頁面入口配置;',
  `sort_type` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '排序類型： 區塊1；區塊2',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 494 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '侧边栏配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_source
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_source`;
CREATE TABLE `tb_game_source`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `game_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏id',
  `remark` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `sort` int(11) NULL DEFAULT NULL COMMENT '游戏排序值',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `logo_web` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'web端图标',
  `logo_h5` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'h5图标',
  `venues_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属场馆code',
  `venues_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属场馆名称',
  `line_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线路状态：ENABLED-正常；DISABLED-异常',
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类code',
  `status_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护/停用/异常时间',
  `maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间起始',
  `maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间结束',
  `remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '停止时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏源' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_transfer_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_transfer_log`;
CREATE TABLE `tb_game_transfer_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转账订单号',
  `related_order_no` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转账订单号',
  `trigger_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '触发来源',
  `uid` bigint(20) NULL DEFAULT NULL COMMENT '会员uid',
  `member_id` bigint(20) NULL DEFAULT NULL COMMENT '会员主键id',
  `game_account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员游戏账户',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员账户',
  `direction` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方向：IN-转入，OUT-转出',
  `stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阶段：INIT-初始化，CHECK-检查余额，FROM_PROVIDER-从供应商转出，TO_VENUE-转入到场馆钱包，TO_CENTER-转入到中心钱包, TO_PROVIDER-转入到供应商, FROM_VENUE-从场馆钱包转出, FROM_CENTER-从中心钱包转出',
  `transfer_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转账状态：SUCCESS-成功, FAILED-失败, PENDING-处理中',
  `provider_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏厂商code',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆code',
  `currency` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转账币种',
  `transfer_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '总转账金额',
  `transfer_amount_center` decimal(20, 2) NULL DEFAULT NULL COMMENT '中心钱包转账金额',
  `transfer_amount_venue` decimal(20, 2) NULL DEFAULT NULL COMMENT '场馆钱包转账金额',
  `target_balance` decimal(20, 2) NULL DEFAULT NULL COMMENT '目标余额',
  `transfer_time` datetime NULL DEFAULT NULL COMMENT '转账时间',
  `has_more` tinyint(4) NULL DEFAULT 0 COMMENT '是否有更多余额',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原因',
  `retry_time` bigint(20) NULL DEFAULT 0 COMMENT '重试锁定时间',
  `retry_count` int(11) NULL DEFAULT 0 COMMENT '补偿/重试次数',
  `retry_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重试补偿方式',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `origin_order_no` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始注单号，用于重试订单关联查询',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_game_transfer_log_order_no_IDX`(`order_no` ASC, `provider_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no` ASC, `provider_code` ASC) USING BTREE,
  INDEX `tb_game_transfer_idx`(`transfer_status` ASC, `retry_time` ASC, `retry_count` ASC) USING BTREE,
  INDEX `idx_uid_providercode_direction_transferamount`(`uid` ASC, `provider_code` ASC, `direction` ASC, `transfer_amount` ASC) USING BTREE,
  INDEX `idx_retrycount_retrytime`(`retry_count` ASC, `retry_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 434998 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'COLUMNAR=1 游戏转账记录表' ROW_FORMAT = DYNAMIC;

