  INDEX `idx_uid`(`uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5194 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏转账记录最新' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_valid_bet_setting
