-- ----------------------------
-- Table structure for tb_game_valid_bet_setting_child
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_valid_bet_setting_child`;
CREATE TABLE `tb_game_valid_bet_setting_child`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `remark` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `absolute_value_switch` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '按输赢绝对值计算有效投注开关:Y/N',
  `min_value_switch` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取最小值作为有效投注:Y/N',
  `max_odds_switch` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '按最大赔率计算有效投注:N/Y',
  `max_odds_val` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '最大赔率计算有效投注数值',
  `low_odds_switch` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '低赔率不计算有效投注:Y/N',
  `low_odds_val` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '低赔率计算有效投注数值',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '父类id',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '子单类型：SPORT-体育；ESPORT-电竞；LOTTERY-彩票',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏有效投注设置子表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_valid_bet_setting_ignore
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_valid_bet_setting_ignore`;
CREATE TABLE `tb_game_valid_bet_setting_ignore`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `remark` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `game_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `game_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏id',
  `venues_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆名称',
  `venues_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆code',
  `add_time` bigint(20) NULL DEFAULT NULL COMMENT '添加时间',
  `status` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '\"DISABLED\";\"ENABLED\"',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏有效投注设置不计算表\r\n（废弃）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_game_venue_wallet
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_venue_wallet`;
CREATE TABLE `tb_game_venue_wallet`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员账号',
  `category` smallint(6) NOT NULL COMMENT '品类',
  `provider_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商编码',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆编码',
  `balance` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '钱包余额',
  `flag` smallint(6) NOT NULL DEFAULT 0 COMMENT '标志',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_uid_venue`(`uid` ASC, `venue_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_uid_provider_category`(`uid` ASC, `provider_code` ASC, `category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏场馆钱包' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_game_venue_wallet_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_game_venue_wallet_log`;
CREATE TABLE `tb_game_venue_wallet_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uid` bigint(20) NOT NULL COMMENT '会员UID',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员账号',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `related_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联订单号',
  `category` smallint(6) NOT NULL COMMENT '品类',
  `provider_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商编码',
  `venue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆编码',
  `transfer_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '转账源头：GAME,FUND,PROVIDER,ACTIVITY',
  `transfer_target` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '转账目标：GAME,FUND,PROVIDER,ACTIVITY',
  `balance_change` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '变化余额',
  `balance_before` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '变化前余额',
  `balance_after` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '变化后余额',
  `flag` smallint(6) NOT NULL DEFAULT 0 COMMENT '标志',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_uid_order_no`(`uid` ASC, `order_no` ASC) USING BTREE,
  INDEX `idx_uid_venue`(`uid` ASC, `flag` ASC, `venue_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏场馆钱包账变日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_gb_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_gb_bet_raw_log`;
CREATE TABLE `tb_gb_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `gameplat` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏平台 (web 或 mobile)',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员游戏账户',
  `round` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单订单号',
  `gamecode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏code',
  `balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '余额，最大为 20 位数字，精确到小数点后 4 位',
  `win` decimal(20, 4) NULL DEFAULT NULL COMMENT '游戏赢分，最大为 20 位数字，精确到小数点后 4 位',
  `bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `validbet` decimal(20, 4) NULL DEFAULT NULL COMMENT '有效下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注状态:',
  `bettime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注时间 (可以选择改为时间戳类型)',
  `createtime` bigint(20) NULL DEFAULT NULL COMMENT '當筆資料建立時間',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币类型',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '接口返回结果，使用 TEXT 类型存储 JSON 数据',
  `tracecode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接口响应标识',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `is_change` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据是否有变动： Y-是 ，N-否',
  `gametype` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏品类：slot-老虎機，fish-捕魚遊戲,arcade-街機遊戲，table-桌上遊戲，live-真人視訊,lotto-彩票遊戲 dealergame-荷官發牌遊戲 sports-體育,livegame-彈珠遊戲,animal-鬥雞',
  `pull_time` bigint(20) NULL DEFAULT NULL COMMENT '拉取时间',
  `md5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '字段值md5(排除主键ID,创建人,更新人,创建时间和更新时间)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `round_idx`(`round` ASC) USING BTREE,
  INDEX `idx_bettime`(`bettime` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 238836 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'gameBoy厂商原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_gpi_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_gpi_bet_raw_log`;
CREATE TABLE `tb_gpi_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bet_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注ID',
  `bundle_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '捆绑ID',
  `round_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '回合ID',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户ID',
  `trans_date` datetime NOT NULL COMMENT '交易时间',
  `game_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类型',
  `game_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏ID',
  `game_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏代码',
  `table_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桌子ID',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台',
  `bet` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '投注金额',
  `winlose` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '输赢金额',
  `balance` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '余额',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币',
  `status` tinyint(4) NULL DEFAULT NULL COMMENT '状态(1-已结算)',
  `game_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏结果',
  `player_hand` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家牌型/投注类型',
  `lucky_num` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '幸运号码',
  `fround` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'fround',
  `jcon` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'jcon',
  `jwin` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'jwin',
  `rebate_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '返水金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_gpi_bet_raw_log_bundle_id_IDX`(`bundle_id` ASC) USING BTREE,
  INDEX `idx_trans_date`(`trans_date` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3237 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'GPI投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_gw_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_gw_bet_raw_log`;
CREATE TABLE `tb_gw_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏商注单ID',
  `user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏商用户ID',
  `package_id` int(11) NOT NULL COMMENT '包ID',
  `task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务ID',
  `lottery_id` int(11) NOT NULL COMMENT '彩种ID',
  `method_id` int(11) NOT NULL COMMENT '玩法ID',
  `issue` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '彩种奖期ID',
  `bonus` decimal(20, 4) NOT NULL COMMENT '实际中奖金额',
  `winbonus` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '预计单注中奖金额',
  `code` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注号码',
  `code_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注类型',
  `single_price` decimal(20, 6) NOT NULL COMMENT '单注金额',
  `multiple` int(11) NOT NULL COMMENT '倍数',
  `total_price` decimal(20, 6) NOT NULL COMMENT '注单实际扣款金额',
  `write_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单写入时间',
  `scode` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注号码(scode)',
  `raw_update_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '方案更新时间(原始字段名称update_time)',
  `deduct_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '真实扣款时间',
  `bonus_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '奖金派发时间',
  `cancel_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '撤单时间',
  `is_deduct` int(1) NOT NULL COMMENT '是否已扣款 (0:未扣款; 1:已扣款)',
  `is_cancel` int(1) NOT NULL COMMENT '是否撤单',
  `is_getprize` int(1) NOT NULL COMMENT '中奖状态 (0:未判断; 1:中奖; 2:未中奖)',
  `prize_status` int(1) NOT NULL COMMENT '派奖状态 (0:未派; 1:已派)',
  `game_cancel_count` int(11) NOT NULL COMMENT '游戏取消次数',
  `user_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户IP',
  `modes` int(4) NOT NULL COMMENT '模式 (1:元; 2:角; 3:分)',
  `hashvar` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '哈希值',
  `user_point` decimal(20, 4) NOT NULL COMMENT '用户返点金额',
  `is_new` int(1) NOT NULL COMMENT '是否特别奖金组 (1:是; 0:否)',
  `comefrom` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源',
  `point_status` int(1) NOT NULL COMMENT '返点状态 (1:已返点; 0:未返点)',
  `third_party_trx_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方交易ID',
  `platform` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台',
  `log` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '日志',
  `created_at` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据创建时间',
  `updated_at` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据更新时间',
  `pointinfo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '返点信息',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币类型',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '第三方用户ID',
  `thirdparty_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '第三方用户ID',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户代号',
  `lottery_group` int(11) NOT NULL COMMENT '彩种组',
  `cnname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '彩种中文名称',
  `enname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '彩种英文名称',
  `method_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩法名称',
  `bingo_code` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开奖号码',
  `bingo_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开奖时间',
  `sale_start` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '彩种奖期开始销售时间',
  `sale_end` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '彩种奖期结束销售时间',
  `belong_date` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '属于日期',
  `op_id` int(11) NOT NULL COMMENT '操作员ID',
  `expected_profit` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '预期利润',
  `actual_profit` decimal(20, 6) NOT NULL COMMENT '实际利润',
  `one_price` decimal(20, 6) NOT NULL COMMENT '单价',
  `project_display_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户注单编号显示用',
  `status_flag` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单状态',
  `i18n_lottery_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化彩种名称',
  `i18n_lottery_name_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化彩种名称键',
  `i18n_method_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化玩法名称',
  `i18n_method_name_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化玩法名称键',
  `i18n_method_lv1_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化玩法一级名称',
  `i18n_method_lv1_name_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化玩法一级名称键',
  `i18n_status_flag` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化注单状态',
  `i18n_status_flag_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国际化注单状态键',
  `cnname_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '彩种中文名称键',
  `method_name_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩法名称键',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `project_id_idex`(`project_id` ASC) USING BTREE,
  INDEX `idx_write_time`(`write_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1507 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'GW原始注单日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_im_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_im_bet_raw_log`;
CREATE TABLE `tb_im_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID，主键',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '接口返回结果',
  `trace_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接口响应标识',
  `pull_time` bigint(20) NULL DEFAULT NULL COMMENT '拉取时间 (时间戳)',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间 (时间戳)',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间 (时间戳)',
  `round` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单号',
  `account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员游戏账户',
  `game_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏code',
  `bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `detail` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '子表',
  `outcome` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏输赢',
  `total_day_win_loss_amount` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '输赢金额',
  `wager_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `wager_event_date_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '赛事时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_im_bet_raw_log_round_IDX`(`round` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104843 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_jdb_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_jdb_bet_raw_log`;
CREATE TABLE `tb_jdb_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `history_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏序号',
  `player_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家账号',
  `g_type` int(11) NOT NULL COMMENT '游戏类型',
  `m_type` int(11) NOT NULL COMMENT '机台类型',
  `game_date` datetime NOT NULL COMMENT '游戏时间',
  `bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '押注金额',
  `win` decimal(20, 4) NULL DEFAULT NULL COMMENT '游戏赢分',
  `total` decimal(20, 4) NULL DEFAULT NULL COMMENT '总输赢',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币代码',
  `jackpot` decimal(20, 4) NULL DEFAULT NULL COMMENT '赢得彩金金额',
  `jackpot_contribute` decimal(20, 4) NULL DEFAULT NULL COMMENT '彩金贡献值',
  `denom` decimal(20, 4) NULL DEFAULT NULL COMMENT '投注面值',
  `last_modify_time` datetime NULL DEFAULT NULL COMMENT '最后修改时间',
  `player_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家登入IP',
  `client_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家从网页或行动装置登入',
  `has_freegame` tinyint(1) NULL DEFAULT 0 COMMENT '是否免费游戏：0-否 1-是',
  `system_take_win` tinyint(1) NULL DEFAULT 0 COMMENT '是否系统结算：0-否 1-是',
  `before_balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '进场金额',
  `after_balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '离场金额',
  `room_type` int(11) NULL DEFAULT NULL COMMENT '游戏区域：-1-大厅 0-小压码区 1-中压码区 2-大压码区',
  `resp_json` json NULL COMMENT '原始响应数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_jdb_bet_raw_log_history_id_IDX`(`history_id` ASC) USING BTREE,
  INDEX `idx_game_date`(`game_date` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6552 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'JDB游戏原始投注记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_jili_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_jili_bet_raw_log`;
CREATE TABLE `tb_jili_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `Account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员唯一识别值(会员游戏账户)',
  `WagersId` bigint(20) NOT NULL COMMENT '在游戏内注单唯一值（注单号）',
  `GameId` int(11) NOT NULL COMMENT '游戏ID（吉利游戏厂商游戏id）',
  `WagersTime` datetime(6) NOT NULL COMMENT '投注时间',
  `BetAmount` decimal(16, 4) NOT NULL DEFAULT 0.0000 COMMENT '投注金额',
  `PayoffTime` datetime(6) NOT NULL COMMENT '派彩时间',
  `PayoffAmount` decimal(16, 2) NOT NULL DEFAULT 0.00 COMMENT '派彩金额',
  `Status` int(11) NOT NULL COMMENT '注单状态： 1: 赢 2: 输 3: 平局',
  `SettlementTime` datetime(6) NOT NULL COMMENT '对帐时间',
  `GameCategoryId` int(11) NOT NULL COMMENT '游戏类型：1-电子 2-棋牌 3-游戏大厅 5-捕鱼 6-押分机 (含宾果)',
  `Type` int(11) NOT NULL COMMENT '注单类型： 1-一般下注 9-舞龙争霸和梅杜莎的bonus game 11-道具卡 12-游戏内购 13-满额必开 (下注) 18-满额必开 (开奖) 19-免费游戏 28-旋转奖金 (Spin Bonus)',
  `AgentId` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员所属站长唯一识别值',
  `RoundIndex` bigint(20) NULL DEFAULT NULL COMMENT '主单号，用于注单类型为 9 的注单',
  `Turnover` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '有效投注金额',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(6) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(6) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `wagers_id_index`(`WagersId` ASC) USING BTREE,
  INDEX `idx_WagersTime`(`WagersTime` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27270 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '吉利游戏厂商原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_ka_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_ka_bet_raw_log`;
CREATE TABLE `tb_ka_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `player_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家标识符',
  `operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家隶属的合作伙伴子品牌或代理商',
  `transaction_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏交易标识符。一般游戏与触发的免费游戏共享同一个游戏交易标识符',
  `game_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏标识符',
  `game_type` enum('slots','fish','vpoker','pyp','other','table') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏种类',
  `spin_date` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '指定时区下玩家该局的下注时间（例如：2017-06-21 15:56:18）',
  `tz_offset` int(11) NOT NULL COMMENT '时区，以小时为单位的 UTC+0 偏移量（例如：UTC-4 请使用 -4）',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币代码（ISO 4217）',
  `rtp` float NOT NULL COMMENT '游戏的玩家回报率',
  `denomination` float NOT NULL COMMENT '积分面值',
  `selections` int(11) NOT NULL COMMENT '赔付线游戏的下注线数或方式游戏的转轮数',
  `credit_per_selection` bigint(20) NOT NULL COMMENT '赔付线游戏的单线下注积分或方式游戏的下注积分倍数',
  `cash_played` bigint(20) NOT NULL COMMENT '玩家该局的下注金额，以分为单位',
  `cash_played_raw` bigint(20) NOT NULL COMMENT '玩家该局的下注金额（不包含合作伙伴的货币乘数），以分为单位',
  `cash_won` bigint(20) NOT NULL COMMENT '玩家该局赢得派彩，以分为单位',
  `cash_won_raw` bigint(20) NOT NULL COMMENT '玩家该局赢得派彩（不包含合作伙伴的货币乘数），以分为单位',
  `credits_played` bigint(20) NOT NULL COMMENT '玩家该局的下注积分',
  `credits_won` bigint(20) NOT NULL COMMENT '玩家该局赢得积分',
  `free_spin` tinyint(1) NOT NULL COMMENT '是否为免费游戏（1=True，0=False）',
  `round` int(11) NOT NULL COMMENT '该局为免费游戏的第几回合',
  `rounds_remaining` int(11) NOT NULL COMMENT '该局游戏后，剩余的免费游戏次数',
  `complete` tinyint(1) NOT NULL COMMENT '该局游戏是否有未完成的奖励游戏（1=True，0=False）',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `transaction_id_idx`(`transaction_id` ASC) USING BTREE,
  INDEX `idx_spin_date`(`spin_date` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40398 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Ka原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_km_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_km_bet_raw_log`;
CREATE TABLE `tb_km_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '全球唯一标识符',
  `round_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'UGS内部的交易回合(round)唯一辨识代码',
  `ugs_bet_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'KM内部投注辨识码',
  `tx_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来自游戏供应商的交易或投注辨识码',
  `bet_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外部的投注辨识码(来自游戏供应商)',
  `round_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告时间的游戏回合状态',
  `gp_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商代码',
  `platform_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏平台的类型',
  `bet_on` datetime(3) NULL DEFAULT NULL COMMENT '记录在KM服务器的投注时间',
  `closed_on` datetime(3) NULL DEFAULT NULL COMMENT '投注关闭的时间',
  `bet_updated_on` datetime(3) NULL DEFAULT NULL COMMENT '投注更新的时间',
  `timestamp` datetime(3) NULL DEFAULT NULL COMMENT '游戏供应商处理动作的时间戳',
  `user_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家专属辨识代码',
  `user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家用户名',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家于KM系统使用的货币',
  `risk_amount` decimal(20, 6) NULL DEFAULT NULL COMMENT '投注的总金额',
  `win_amount` decimal(20, 6) NULL DEFAULT NULL COMMENT '投注赢的金额',
  `valid_bet` decimal(20, 6) NULL DEFAULT NULL COMMENT '回合中所有投注的有效投注总金额',
  `commission` decimal(20, 6) NULL DEFAULT NULL COMMENT '下注玩家的佣金金额',
  `win_loss` decimal(20, 6) NULL DEFAULT NULL COMMENT '下投注的净总金额',
  `before_balance` decimal(20, 6) NULL DEFAULT NULL COMMENT '投注交易前玩家的余额',
  `post_balance` decimal(20, 6) NULL DEFAULT NULL COMMENT '投注交易后玩家的余额',
  `game_provider` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商的名称',
  `game_provider_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商代码',
  `game_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `game_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏id',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商报告的玩家IP地址',
  `bet_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '永远是\"PlaceBet\"',
  `play_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类型',
  `player_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用来辨识转账的玩家为真实玩家或测试玩家',
  `turnover` decimal(20, 6) NULL DEFAULT NULL COMMENT '回合中所有投注的流水额',
  `jackpot_contribution` decimal(20, 6) NULL DEFAULT NULL COMMENT '有效投注总金额中，貢獻到jackpot的金額',
  `jackpot_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'jackpot的ID',
  `jackpot_win_amount` int(11) NULL DEFAULT NULL COMMENT '玩家中奖的彩金金额',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_record_id`(`record_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_ugs_bet_id`(`ugs_bet_id` ASC) USING BTREE,
  INDEX `idx_bet_on`(`bet_on` ASC) USING BTREE,
  INDEX `idx_round_id`(`round_id` ASC) USING BTREE,
  INDEX `idx_game_id`(`game_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5473 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'KM原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_member_general_report_all
-- ----------------------------
DROP TABLE IF EXISTS `tb_member_general_report_all`;
CREATE TABLE `tb_member_general_report_all`  (
  `id` bigint(32) NOT NULL AUTO_INCREMENT,
  `uid` bigint(20) NOT NULL COMMENT '唯一id',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员账号',
  `agent` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `grade` bigint(20) NULL DEFAULT NULL COMMENT '会员等级',
  `grade_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `register_source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `level_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `net_profit_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '盈亏',
  `win_lose_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '玩家输赢金额/净输赢（有负数）',
  `calc_valid_bet_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '打码(二次计算有效投注金额)',
  `deposit_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '存款金额（总充值）',
  `deposit_number` bigint(20) NULL DEFAULT 0 COMMENT '存款笔数',
  `deposit_days` bigint(20) NULL DEFAULT 0 COMMENT '存款天数',
  `withdraw_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '提款金额',
  `withdraw_number` bigint(20) NULL DEFAULT 0 COMMENT '提款笔数',
  `deposit_withdraw_diff_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '存提差额',
  `manual_add_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '人工加额',
  `manual_sub_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '人工减额',
  `bonus_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '红利金额',
  `welfare_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '福利金额',
  `rebate_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '返水金额',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '数据时间戳',
  `bet_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '总投注金额',
  `payout_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '总中奖(总派彩额)',
  `effect_bet_days` bigint(32) NULL DEFAULT 0 COMMENT '有效投注天数',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `deposit_times` int(11) NULL DEFAULT 0 COMMENT '存款次数',
  `first_deposit_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '首存金额',
  `first_deposit_time` bigint(20) NULL DEFAULT NULL COMMENT '首存时间',
  `second_deposit_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '二存金额',
  `second_deposit_time` bigint(20) NULL DEFAULT NULL COMMENT '二存时间',
  `second_deposit_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二存状态',
  `last_deposit_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '最后存款金额',
  `last_deposit_time` bigint(20) NULL DEFAULT NULL COMMENT '最后存款时间',
  `last_withdraw_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '最后提现金额',
  `last_withdraw_time` bigint(20) NULL DEFAULT 0 COMMENT '最后提现时间',
  `bet_multi` int(11) NULL DEFAULT 0 COMMENT '投注倍数',
  `first_withdraw_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '首提现金额',
  `first_withdraw_time` bigint(20) NULL DEFAULT NULL COMMENT '首提现时间',
  `first_withdraw_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '首提现金额',
  `first_deposit_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '首提现金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_uid_account`(`uid` ASC, `account` ASC) USING BTREE,
  INDEX `idx_grade`(`grade` ASC) USING BTREE,
  INDEX `idx_account`(`account` ASC) USING BTREE,
  INDEX `idx_cover`(`agent` ASC, `grade` ASC, `register_source` ASC) USING BTREE,
  INDEX `idx_register_source`(`register_source` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 109097758 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员总报表-全量表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_mg_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_mg_bet_raw_log`;
CREATE TABLE `tb_mg_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bet_uid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注唯一标识',
  `created_date_utc` datetime(3) NULL DEFAULT NULL COMMENT '创建时间UTC',
  `game_start_time_utc` datetime(3) NULL DEFAULT NULL COMMENT '游戏开始时间UTC',
  `game_end_time_utc` datetime(3) NULL DEFAULT NULL COMMENT '游戏结束时间UTC',
  `player_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家ID',
  `product_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品ID',
  `product_player_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品玩家ID',
  `platform` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台',
  `game_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏代码',
  `channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币类型',
  `bet_amount` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '投注金额',
  `payout_amount` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '派彩金额',
  `bet_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注状态',
  `pca` decimal(18, 4) NULL DEFAULT NULL COMMENT 'PCA值',
  `external_transaction_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外部交易ID',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会话ID',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易ID',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述信息',
  `is_free_game` tinyint(1) NULL DEFAULT 0 COMMENT '是否免费游戏 0-否 1-是',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始JSON数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bet_uid`(`bet_uid` ASC) USING BTREE,
  INDEX `idx_bet_uid`(`bet_uid` ASC) USING BTREE,
  INDEX `idx_created_date_utc_desc`(`created_date_utc` DESC) USING BTREE,
  INDEX `idx_created_date_utc`(`created_date_utc` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4545539 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'MG投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_mw_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_mw_bet_raw_log`;
CREATE TABLE `tb_mw_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `firm_id` int(11) NULL DEFAULT NULL COMMENT '商户ID',
  `merchant_id` int(11) NULL DEFAULT NULL COMMENT '商户ID',
  `uid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户ID',
  `game_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `game_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏ID',
  `game_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类别：正常：0、免费游戏：1、比倍：10、购买特色游戏：5',
  `wager_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '下注单号(唯一)，mw lobby 产生',
  `game_round_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注局号(唯一)，游戏伺服器产生',
  `risk` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否为无风险下注，0 为无风险，1 为有风险',
  `play_money` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩分，精确到小数点后两位，单位：根据货币单位',
  `win_money` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赢分，精确到小数点后两位，单位：根据货币单位',
  `log_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录时间，yyyy-MM-dd HH:mm:ss 格式，北京时间',
  `currency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币',
  `init_bet` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始押注，精确到小数点后两位，单位：根据货币单位',
  `commission` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间内抽水，到小数点第二位，单位：根据货币单位',
  `category` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类型，1.捕鱼 2.棋牌 3.电子游戏机',
  `device` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '装置\"PC\" or \"MOBILE\"',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wager_id`(`wager_id` ASC) USING BTREE,
  INDEX `idx_merchant_id`(`merchant_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_uid`(`uid` ASC) USING BTREE,
  INDEX `idx_firm_id`(`firm_id` ASC) USING BTREE,
  INDEX `idx_game_id`(`game_id` ASC) USING BTREE,
  INDEX `idx_log_date`(`log_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3268 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'MW投注记录原始表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_ns_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_ns_bet_raw_log`;
CREATE TABLE `tb_ns_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `ticket_id` bigint(20) NOT NULL COMMENT '投注单号',
  `acct_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账户ID',
  `category_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏分类ID',
  `game_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏代码',
  `ticket_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注时间(格式:yyyyMMddTHHmmss)',
  `bet_ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注IP地址',
  `bet_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '投注金额',
  `win_loss` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '输赢金额',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币类型',
  `result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '游戏结果',
  `jackpot_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT 'Jackpot金额',
  `lucky_draw_id` int(11) NULL DEFAULT 0 COMMENT '幸运抽奖ID',
  `completed` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否完成(0:否,1:是)',
  `round_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏回合ID',
  `sequence` int(11) NULL DEFAULT 0 COMMENT '序号',
  `channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道(web/mobile/app等)',
  `balance` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT '余额',
  `jp_win` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT 'JP中奖金额',
  `reference_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参考ID',
  `is_cascade` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否级联(仅测试环境)',
  `is_buy_feature` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否购买功能(仅测试环境)',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ticket_id`(`ticket_id` ASC) USING BTREE,
  INDEX `idx_ticket_time`(`ticket_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 47730 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'NS投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_odin_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_odin_bet_raw_log`;
CREATE TABLE `tb_odin_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Uniq Key By Game Provider',
  `player` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Player Account',
  `bet_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT 'Bet Amount',
  `payout_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT 'Payout Amount',
  `num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Bet Number',
  `type` int(11) NULL DEFAULT NULL COMMENT '接口类型 1：下注 2：结算 3:取消',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_odin_bet_raw_log_num_IDX`(`num` ASC) USING BTREE,
  INDEX `idx_slug`(`slug` ASC) USING BTREE,
  INDEX `idx_player`(`player` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Odin Bet Raw Log' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_on_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_on_bet_raw_log`;
CREATE TABLE `tb_on_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户名',
  `play` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法名称',
  `play_id` int(11) NULL DEFAULT NULL COMMENT '玩法ID',
  `result` int(11) NULL DEFAULT NULL COMMENT '输赢结果 0:输 1:赢 2:平',
  `state` int(11) NULL DEFAULT NULL COMMENT '状态 0:未结算 1:已结算 3:牌局撤销',
  `game_id` int(11) NULL DEFAULT NULL COMMENT '游戏ID',
  `round_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '轮次号',
  `game_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏结果',
  `other_odds` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他赔率',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币',
  `table_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桌台号',
  `odds` decimal(10, 4) NULL DEFAULT NULL COMMENT '赔率',
  `gross_win` decimal(15, 2) NULL DEFAULT NULL COMMENT '总彩金，包括本金',
  `valid_bet_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '有效投注金额',
  `add_time` bigint(20) NULL DEFAULT NULL COMMENT '下注时间',
  `open_time` bigint(20) NULL DEFAULT NULL COMMENT '开奖时间',
  `settle_time` bigint(20) NULL DEFAULT NULL COMMENT '结算时间',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
  `device` int(11) NULL DEFAULT NULL COMMENT '设备类型',
  `win_lose` decimal(15, 2) NULL DEFAULT NULL COMMENT '输赢金额',
  `settle_odds` decimal(10, 4) NULL DEFAULT NULL COMMENT '结算赔率',
  `other_settle_odds` decimal(10, 4) NULL DEFAULT NULL COMMENT '其他结算赔率',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `stake` decimal(15, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `order_type` int(11) NULL DEFAULT 1 COMMENT 'orderType 1:注单 2:打赏',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_open_time`(`open_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_add_time`(`add_time` ASC) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE,
  INDEX `idx_settle_time`(`settle_time` ASC) USING BTREE,
  INDEX `idx_update_time`(`update_time` ASC) USING BTREE,
  INDEX `idx_user_name`(`user_name` ASC) USING BTREE,
  INDEX `idx_game_id`(`game_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1047 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'ON原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_one68g_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_one68g_bet_raw_log`;
CREATE TABLE `tb_one68g_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `gameplat` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏平台 (web 或 mobile)',
  `account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员游戏账户',
  `round` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单订单号',
  `gamecode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏code',
  `balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '余额，最大为 20 位数字，精确到小数点后 4 位',
  `win` decimal(20, 4) NULL DEFAULT NULL COMMENT '游戏赢分，最大为 20 位数字，精确到小数点后 4 位',
  `bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `validbet` decimal(20, 4) NULL DEFAULT NULL COMMENT '有效下注金额，最大为 20 位数字，精确到小数点后 4 位',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注状态:',
  `bettime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注时间 (可以选择改为时间戳类型)',
  `raw_createtime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '當筆資料建立時間(原来字段是createtime)',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币类型',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '接口返回结果，使用 TEXT 类型存储 JSON 数据',
  `tracecode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接口响应标识',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(32) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(32) NULL DEFAULT NULL COMMENT '更新时间',
  `gametype` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏品类：slot-老虎機，fish-捕魚遊戲,arcade-街機遊戲，table-桌上遊戲，live-真人視訊,lotto-彩票遊戲 dealergame-荷官發牌遊戲 sports-體育,livegame-彈珠遊戲,animal-鬥雞',
  `ticketid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免費券id',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注详情',
  `tickettype` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免費券類型\r\n1 = 免費遊戲 ( 獲得一局 free game )\r\n2 = 免費 spin ( 獲得一次 free spin )',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `round_index`(`round` ASC) USING BTREE,
  INDEX `idx_raw_createtime`(`raw_createtime` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6774 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '168g原始注单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_pa_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_pa_bet_raw_log`;
CREATE TABLE `tb_pa_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '统一的投注金额',
  `payout_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '统一的派彩金额',
  `refund_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '统一的退款金额',
  `session_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '服务器验证编码，与Create Game Session一致',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '币种',
  `value` decimal(18, 4) NULL DEFAULT NULL COMMENT '投注金额，精确到小数后4位',
  `valid_bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '有效投注金额，精确到小数后4位',
  `net_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '赢/输金额，精确到小数后4位',
  `playname` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '游戏账号(productId+username，区分大小写)',
  `agent_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '代理编码',
  `bet_time` datetime NOT NULL COMMENT '下注生效时间',
  `transaction_id` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易编号',
  `platform_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '平台类型，如AGIN',
  `round` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '平台游戏厅别类型',
  `gametype` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '游戏类型',
  `game_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '游戏局号',
  `table_code` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '台号',
  `transaction_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易类型：BET/WIN/LOSE/REFUND',
  `transaction_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '真人下注交易代码',
  `device_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '设备类型：DESKTOP/MOBILE',
  `playtype` int(11) NULL DEFAULT NULL COMMENT '下注玩法',
  `settletime` datetime NULL DEFAULT NULL COMMENT '下注生效时间',
  `bill_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易编号/注单号',
  `ticket_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '派彩状态，包括赢、输、下注、退款',
  `game_result` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '游戏结果',
  `finish` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '该局的最后一注派彩',
  `amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '交易金额，為非负数，数值准确至小数后4个位(slot)',
  `game_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '游戏识别码(slot)',
  `round_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '游戏局号(slot)',
  `time` datetime NULL DEFAULT NULL COMMENT '玩家下注生效时间，格式: 月/日/年 时:分:秒(slot)',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '游戏详情，不同游戏可能会有不同格式(slot)',
  `event_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '活动编码，请参考附录：活动编码(event)',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `udx_transaction_id_bill_no`(`transaction_id` ASC, `bill_no` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_bill_no`(`bill_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5809 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'PA原始注单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_pd_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_pd_bet_raw_log`;
CREATE TABLE `tb_pd_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'User name',
  `merchant_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Merchant code',
  `odds` decimal(20, 4) NULL DEFAULT NULL COMMENT '赔率',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Order ID',
  `order_status` tinyint(4) NOT NULL COMMENT 'Order status',
  `order_type` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'Order type: 1=normal, 2=reservation, 3=group buy',
  `original_create_time` bigint(20) NOT NULL COMMENT 'Bet time (13-digit timestamp)',
  `modify_time` bigint(20) NULL DEFAULT NULL COMMENT 'Order update time',
  `order_amount` decimal(20, 4) NOT NULL COMMENT 'Actual bet amount',
  `bet_count` int(11) NULL DEFAULT 1 COMMENT 'Number of bet items',
  `settle_time` bigint(20) NULL DEFAULT NULL COMMENT 'Settlement time',
  `settle_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Settlement amount',
  `pre_bet_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Pre-settlement bet amount',
  `profit_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Profit amount',
  `outcome` tinyint(4) NULL DEFAULT NULL COMMENT 'Settlement result: 2=push, 3=lose, 4=win, 5=half win, 6=half lose, 7=match cancelled, 8=match postponed',
  `series_type` int(11) NULL DEFAULT NULL COMMENT 'Series type',
  `series_value` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Series value',
  `settle_times` int(11) NULL DEFAULT 0 COMMENT 'Settlement count',
  `device_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Device type: 1=H5, 2=PC, 3=Android, 4=iOS',
  `device_imei` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Mobile device identifier',
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '语言代码，如zs',
  `sport_id` int(11) NULL DEFAULT NULL COMMENT '赛种ID',
  `sport_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `match_code` int(11) NULL DEFAULT NULL COMMENT '比赛代码',
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP address',
  `currency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Currency',
  `exchange_rate` decimal(20, 8) NULL DEFAULT NULL COMMENT 'Exchange rate',
  `max_win_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Maximum win amount',
  `vip_level` int(11) NULL DEFAULT NULL COMMENT 'VIP level',
  `before_transfer` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Balance before transfer',
  `after_transfer` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Balance after transfer',
  `valid_order_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT 'Valid bet amount',
  `detail_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '子单列表',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注單json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_pd_bet_raw_log_order_no_IDX`(`order_no` ASC) USING BTREE,
  INDEX `idx_original_create_time`(`original_create_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 628 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'PD投注记录原始表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_pg_bet_raw_order_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_pg_bet_raw_order_log`;
CREATE TABLE `tb_pg_bet_raw_order_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '唯一标识符（自动增长）',
  `bet_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子投注的唯一标识符（唯一键值）',
  `parent_bet_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '母注单的唯一标识符',
  `player_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家的唯一标识符',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录中玩家使用的货币',
  `game_id` int(11) NULL DEFAULT NULL COMMENT '游戏的唯一标识符',
  `platform` int(11) NULL DEFAULT NULL COMMENT '投注记录平台（请参考平台以获取更多信息）',
  `bet_type` int(11) NULL DEFAULT NULL COMMENT '投注记录类别：1：真实游戏',
  `transaction_type` int(11) NULL DEFAULT NULL COMMENT '交易类别：0：调整后的投注（重置游戏状态），1：现金，2：红利，3：免费游戏',
  `bet_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家的投注金额',
  `win_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家的所赢金额',
  `jackpot_rtp_contribution_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家的奖池回报率贡献金额',
  `jackpot_contribution_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家的奖池贡献金额',
  `jackpot_win_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家的奖池中奖金额',
  `balance_before` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家交易前的余额',
  `balance_after` decimal(15, 2) NULL DEFAULT NULL COMMENT '玩家交易后的余额',
  `hands_status` int(11) NULL DEFAULT NULL COMMENT '投注状态：1：非最后一手投注，2：最后一手投注，3：已调整',
  `row_version` bigint(20) NULL DEFAULT NULL COMMENT '数据更新时间（以毫秒为单位的 Unix 时间戳）',
  `bet_time` bigint(20) NULL DEFAULT NULL COMMENT '当前投注的开始时间（以毫秒为单位的 Unix 时间戳）',
  `bet_end_time` bigint(20) NULL DEFAULT NULL COMMENT '当前投注的结束时间（以毫秒为单位的 Unix 时间戳）',
  `is_feature_buy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表示旋转类型：True：奖金游戏，False：普通旋转',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '记录创建时间（Unix 时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '记录更新时间（Unix 时间戳）',
  `deleted` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录是否已删除',
  `md5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '字段值md5(排除主键ID,创建人,更新人,创建时间和更新时间)',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bet_id`(`bet_id` ASC) USING BTREE,
  INDEX `bet_id_idx`(`bet_id` ASC) USING BTREE,
  INDEX `row_version_idx`(`row_version` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51125394 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'PG SOFT游戏原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_pp_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_pp_bet_raw_log`;
CREATE TABLE `tb_pp_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `game_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏ID',
  `game_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `resp_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON数据',
  `ext_player_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外部玩家ID',
  `play_session_id` bigint(20) NULL DEFAULT NULL COMMENT '游戏会话ID',
  `type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类型',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态',
  `start_date` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `end_date` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `bet` decimal(18, 2) NULL DEFAULT NULL COMMENT '投注金额',
  `win` decimal(18, 2) NULL DEFAULT NULL COMMENT '赢取金额',
  `jackpot` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '奖池金额',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除标识(0:未删除,1:已删除)',
  `balance` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '余额',
  `platform` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'U -  未知\r\nW - 桌面设备\r\nM - 移动设备',
  `round_details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提供现场娱乐场游戏的赌注和结果额外信息',
  `bonus_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免费回合奖金的 ID。 适用于 FRB 比赛的回合',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_play_session_id`(`play_session_id` ASC) USING BTREE,
  INDEX `idx_start_date`(`start_date` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7199 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'PP投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_r88_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_r88_bet_raw_log`;
CREATE TABLE `tb_r88_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `record_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录ID',
