  `account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账户',
  `bet_status` int(11) NULL DEFAULT NULL COMMENT '投注状态',
  `base_bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '基础投注',
  `bet` decimal(20, 4) NULL DEFAULT NULL COMMENT '投注金额',
  `bet_valid` decimal(20, 4) NULL DEFAULT NULL COMMENT '有效投注金额',
  `profit` decimal(20, 4) NULL DEFAULT NULL COMMENT '利润',
  `tax` decimal(20, 4) NULL DEFAULT NULL COMMENT '税收',
  `balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '余额',
  `bonus` decimal(20, 4) NULL DEFAULT NULL COMMENT '奖金',
  `result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注结果',
  `round_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '局号',
  `round_start_at` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '局开始时间',
  `round_end_at` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '局结束时间',
  `currency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏分类',
  `purchase_method` int(11) NULL DEFAULT NULL COMMENT '购买方式',
  `main_cascade` int(11) NULL DEFAULT NULL COMMENT '主级联',
  `free_cascade` int(11) NULL DEFAULT NULL COMMENT '免费级联',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间（时间戳，毫秒）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间（时间戳，毫秒）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `record_id_UNIQUE`(`record_id` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4926 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'R88原始投注记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_raw_bet_consume_log
-- ----------------------------
