-- ----------------------------
-- Table structure for tb_sa_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_sa_bet_raw_log`;
CREATE TABLE `tb_sa_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `bet_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注时间',
  `payout_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算时间',
  `username` varchar(48) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户名',
  `host_id` int(11) NULL DEFAULT NULL COMMENT '集合ID',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '保留字段',
  `game_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏编号',
  `game_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类型',
  `round_num` int(11) NULL DEFAULT NULL COMMENT '局',
  `set_num` int(11) NULL DEFAULT NULL COMMENT '靴',
  `bet_id` bigint(20) NULL DEFAULT NULL COMMENT '投注编号',
  `bet_type` int(11) NULL DEFAULT NULL COMMENT '投注类型',
  `bet_source` int(11) NULL DEFAULT NULL COMMENT '投注来源',
  `bet_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT '投注金额',
  `rolling` decimal(20, 4) NULL DEFAULT NULL COMMENT '有效投注额/洗码量',
  `result_amount` decimal(20, 4) NULL DEFAULT NULL COMMENT '输赢金额',
  `balance` decimal(20, 4) NULL DEFAULT NULL COMMENT '投注后的余额',
  `currency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种',
  `transaction_id` bigint(20) NULL DEFAULT NULL COMMENT '单一钱包下注交易编号',
  `bet_confirmation` int(11) NULL DEFAULT NULL COMMENT '确认方式: 0-手动, 1-自动',
  `resp_xml` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单xml',
  `gift_txn_id` bigint(20) NULL DEFAULT NULL COMMENT '打赏交易编号（用于区分打赏注单）',
  `gift_type` int(11) NULL DEFAULT NULL COMMENT '打赏类型: 1-奖赏1(爱心), 2-奖赏2(鲜花), 3-奖赏3(香槟), 4-奖赏4(电子产品), 5-奖赏5(戒指), 6-奖赏6(钱包), 7-奖赏7(手表), 8-奖赏8(汽车)',
  `gift_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '打赏金额',
  `dealer_id` int(11) NULL DEFAULT NULL COMMENT '荷官ID',
  `dealer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '荷官名',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `bet_id_idx`(`bet_id` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2054 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'SA原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_saba_bet_raw_log
