  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联赛或队伍名称',
  `match_id` int(11) NULL DEFAULT NULL COMMENT '赛事编号',
  `home_id` int(11) NULL DEFAULT NULL COMMENT '主队编号',
  `hometeamname` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主队名称',
  `away_id` int(11) NULL DEFAULT NULL COMMENT '客队编号',
  `awayteamname` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客队名称',
  `team_id` int(11) NULL DEFAULT NULL COMMENT '队伍编号',
  `game_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次编号',
  `match_datetime` datetime NULL DEFAULT NULL COMMENT '赛事开球时间',
  `game_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '虚拟赛事类型',
  `sport_type` int(11) NULL DEFAULT NULL COMMENT '体育种类',
  `sportname` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体育种类名称',
  `bet_type` smallint(6) NULL DEFAULT NULL COMMENT '下注类型',
  `bettypename` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注类型名称',
  `parlay_ref_no` bigint(20) NULL DEFAULT NULL COMMENT '混合过关注单号码',
  `odds` decimal(12, 6) NULL DEFAULT NULL COMMENT '注单赔率',
  `stake` decimal(18, 6) NULL DEFAULT NULL COMMENT '会员投注金额',
  `transaction_time` datetime NULL DEFAULT NULL COMMENT '投注交易时间',
  `ticket_status` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单状态',
  `winlost_amount` decimal(18, 6) NULL DEFAULT NULL COMMENT '输赢金额',
  `after_amount` decimal(18, 6) NULL DEFAULT NULL COMMENT '下注后余额',
  `currency` tinyint(4) NULL DEFAULT NULL COMMENT '币别',
  `winlost_datetime` datetime NULL DEFAULT NULL COMMENT '决胜时间',
  `odds_type` tinyint(4) NULL DEFAULT NULL COMMENT '赔率类型',
  `odds_Info` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率详情',
  `bet_team` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注选项内容',
  `betteamname` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注选项内容名称',
  `exculding` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排除比分',
  `bet_tag` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注标签',
  `home_hdp` decimal(12, 6) NULL DEFAULT NULL COMMENT '主队让球/大小盘球头',
  `away_hdp` decimal(12, 6) NULL DEFAULT NULL COMMENT '客队让球/大小盘球头',
  `hdp` decimal(12, 6) NULL DEFAULT NULL COMMENT '让球/大小盘球头',
  `ou_hdp` decimal(12, 6) NULL DEFAULT NULL COMMENT '篮球总分大小盘球头',
  `betfrom` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注平台',
  `islive` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否滚球',
  `home_score` smallint(6) NULL DEFAULT NULL COMMENT '主队得分',
  `home_score2` smallint(6) NULL DEFAULT NULL COMMENT '主队得分2',
  `away_score` smallint(6) NULL DEFAULT NULL COMMENT '客队得分',
  `away_score2` smallint(6) NULL DEFAULT NULL COMMENT '客队得分2',
  `settlement_time` datetime NULL DEFAULT NULL COMMENT '注单结算时间',
  `custom_info1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商备注1',
  `custom_info2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商备注2',
  `custom_info3` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商备注3',
  `custom_info4` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商备注4',
  `custom_info5` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商备注5',
  `ba_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'BA状态',
  `bet_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注备注',
  `esports_gameid` int(11) NULL DEFAULT NULL COMMENT '电竞游戏类型',
  `total_score` int(11) NULL DEFAULT NULL COMMENT '总进球',
  `risklevelname` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险等级',
  `risklevelnamecs` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险等级(中文)',
  `mmr_percentage` decimal(8, 2) NULL DEFAULT NULL COMMENT '缅甸盘赔率%',
  `version_key` bigint(20) NULL DEFAULT NULL COMMENT '版本号',
  `parlay_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '混合过关信息',
  `resettlementinfo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '重新结算信息',
  `action_date` datetime NULL DEFAULT NULL COMMENT '重新结算时间',
  `balancechange` tinyint(1) NULL DEFAULT NULL COMMENT '余额是否更动',
  `winlost` decimal(18, 6) NULL DEFAULT NULL COMMENT '前次结算输赢金额',
  `action` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重新结算状态',
  `ref_no` bigint(20) NULL DEFAULT NULL COMMENT '零风险投注券注单号',
  `actual_amount` decimal(18, 6) NULL DEFAULT NULL COMMENT '实际扣除额',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `trans_id_idx`(`trans_id` ASC) USING BTREE,
  INDEX `idx_transaction_time`(`transaction_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6269 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'SABA原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_sbo_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_sbo_bet_raw_log`;
CREATE TABLE `tb_sbo_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `ref_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Reference number of the 568Win system.',
  `username` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Unique player name in 568Win system.',
  `sports_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Sports Type of the bet',
  `order_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'The Time that player place bet (格式: 2020-03-12T06:47:32.297)',
  `win_lost_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'The Time use to do accounting on this bet.(格式: 2020-03-12T00:00:00)',
  `settle_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'The time when the bet is settled.(格式: 2020-03-12T07:57:22.52)',
  `modify_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'The Time that this bet been modified(格式: 2020-03-12T07:57:22.52)',
  `odds` decimal(20, 4) NOT NULL COMMENT 'The Odds that player placed on.',
  `odds_style` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'The Odds Style that player placed on. M: Malay odds, H: HongKong odds, E: Euro odds, I: Indonesia odds',
  `stake` decimal(20, 4) NOT NULL COMMENT 'The stake that player placed on.',
  `actual_stake` decimal(20, 4) NOT NULL COMMENT 'The actual stake that player placed on.',
  `currency` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Currency code',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'The Status of Player\'s bets.',
  `win_lost` decimal(20, 4) NOT NULL COMMENT 'The Winlose of Player, do not include player\'s stake',
  `turnover` decimal(20, 4) NOT NULL COMMENT 'The Turnover of Player.',
  `turnover_by_stake` decimal(20, 4) NOT NULL COMMENT 'The Turnover of player by stake',
  `turnover_by_actual_stake` decimal(20, 4) NOT NULL COMMENT 'The Turnover of player by actual stake',
  `net_turnover_by_stake` decimal(20, 4) NOT NULL COMMENT 'The Net Turnover of player by stake',
  `net_turnover_by_actual_stake` decimal(20, 4) NOT NULL COMMENT 'The Net Turnover of player by actual stake',
  `is_half_won_lose` tinyint(1) NULL DEFAULT 0 COMMENT 'Is half won or half lose',
  `is_live` tinyint(1) NULL DEFAULT 0 COMMENT 'Is Live Match or not',
  `max_win_without_actual_stake` decimal(20, 4) NULL DEFAULT NULL COMMENT 'The max winning of player without actual stake',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'The IP that player placed bet',
  `sub_bet` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'Single bet will only got one subBet for the bet detail, and Mix parlay will have mutiple subBets.',
  `is_system_tag_risky` tinyint(1) NULL DEFAULT 0 COMMENT 'When value is True, this player is consider risky by our risk control system.',
  `is_customer_tag_risky` tinyint(1) NULL DEFAULT 0 COMMENT 'When value is True, this player is consider risky by operator.',
  `void_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'The void reason of the sports bet',
  `top_downline` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'The username of your downline or your company',
  `is_cash_out` tinyint(1) NULL DEFAULT 0 COMMENT 'When value is True, this bet has been cashed out',
  `new_game_type` int(11) NULL DEFAULT 0 COMMENT 'New game type identifier',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始注单JSON数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ref_no`(`ref_no` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_username`(`username` ASC) USING BTREE,
  INDEX `idx_order_time`(`order_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4453 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'SBO原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_sexybcrt_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_sexybcrt_bet_raw_log`;
CREATE TABLE `tb_sexybcrt_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `userId` varchar(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户ID 玩家ID',
  `currency` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家货币代码',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏平台名称，如：SEXYBCRT',
  `gameType` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台游戏类型，如：LIVE',
  `gameCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台游戏代码，如：MX-LIVE-001',
  `gameName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏名称，如：BaccaratClassic LongHu',
  `platformTxId` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏商注单号，如：BAC-00101',
  `refPlatformTxId` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单号里的子注单号',
  `roundId` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏商的回合识别码，如：Mexico-01-GA17590001',
  `settleStatus` int(11) NOT NULL DEFAULT 0 COMMENT '结算状态：0-正常，1-结果更改，-1-作废投注',
  `betAmount` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '下注金额',
  `winAmount` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '返还金额（包含下注金额）',
  `turnover` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '游戏平台有效投注',
  `realBetAmount` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '真实下注金额',
  `realWinAmount` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '真实返还金额',
  `betType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏平台的下注项目，如：Banker Player Tie',
  `betTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家下注时间（ISO8601格式）',
  `txTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易时间（ISO8601格式）',
  `updateTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间（ISO8601格式）',
  `txStatus` int(11) NOT NULL COMMENT '交易状态',
  `jackpotBetAmount` decimal(15, 4) NULL DEFAULT 0.0000 COMMENT '累积奖金贡献值',
  `jackpotWinAmount` decimal(15, 4) NULL DEFAULT 0.0000 COMMENT '累积奖金获胜金额',
  `gameInfo` json NULL COMMENT '游戏信息（JSON格式）',
  `isPremium` tinyint(1) NULL DEFAULT 0 COMMENT '是否为高级版本',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `tip` decimal(15, 4) NOT NULL DEFAULT 0.0000 COMMENT '打赏金额',
  `tipInfo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打赏讯息会由游戏商以 JSON 格式提供，依各游戏商回传资讯呈现的资料会有所不同\r\n请您不应针对 tipInfo 内的参数进行验证',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Tip type 打赏类型',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_sexybcrt_bet_raw_log_platformTxId_IDX`(`platformTxId` ASC) USING BTREE,
  INDEX `idx_betTime`(`betTime` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2740 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'SEXYBCRT投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_spade_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_spade_bet_raw_log`;
CREATE TABLE `tb_spade_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_id` bigint(20) NOT NULL COMMENT '票据ID',
  `acct_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账户ID',
  `category_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类ID',
  `game_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏代码',
  `ticket_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '票据时间',
  `bet_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注IP',
  `bet_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `win_loss` decimal(20, 2) NULL DEFAULT NULL COMMENT '输赢',
  `result` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结果',
  `lucky_draw_id` bigint(20) NULL DEFAULT NULL COMMENT '幸运抽奖ID',
  `completed` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否完成',
  `round_id` bigint(20) NULL DEFAULT NULL COMMENT '轮次ID',
  `sequence` int(11) NULL DEFAULT NULL COMMENT '序列',
  `channel` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道',
  `balance` decimal(20, 2) NULL DEFAULT NULL COMMENT '余额',
  `jp_win` decimal(20, 2) NULL DEFAULT NULL COMMENT 'JP赢取',
  `reference_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参考ID',
  `game_feature` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏特性',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应JSON数据',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ticket_id`(`ticket_id` ASC) USING BTREE,
  INDEX `idx_acct_id`(`acct_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_game_code`(`game_code` ASC) USING BTREE,
  INDEX `idx_ticket_time`(`ticket_time` ASC) USING BTREE,
  INDEX `idx_round_id`(`round_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43961 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Spade投注记录原始表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_spribe_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_spribe_bet_raw_log`;
CREATE TABLE `tb_spribe_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id,自增',
  `bet_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单ID',
  `vendor_bet_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商原始注单ID',
  `external_transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '外部交易ID',
  `round_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '回合ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `currency_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币代码，如CNY',
  `game_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏代码',
  `vendor_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商代码',
  `game_category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏分类代码',
  `bet_amount` decimal(15, 4) NOT NULL COMMENT '下注金额',
  `win_amount` decimal(15, 4) NOT NULL COMMENT '赢取金额',
  `win_loss` decimal(15, 4) NOT NULL COMMENT '输赢金额（赢取金额 - 下注金额）',
  `effective_turnover` decimal(15, 4) NOT NULL COMMENT '有效投注额',
  `jackpot_amount` decimal(15, 4) NULL DEFAULT 0.0000 COMMENT '彩金金额',
  `refund_amount` decimal(15, 4) NULL DEFAULT 0.0000 COMMENT '退款金额',
  `status` tinyint(4) NOT NULL COMMENT '注单状态：1-下注，2-结算，3-取消等',
  `is_free_spin` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'FALSE' COMMENT '是否免费旋转：TRUE/FALSE',
  `vendor_bet_time` bigint(20) NOT NULL COMMENT '供应商下注时间戳',
  `vendor_settle_time` bigint(20) NOT NULL COMMENT '供应商结算时间戳',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始响应JSON',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bet_id`(`bet_id` ASC) USING BTREE,
  INDEX `idx_vendor_bet_id`(`vendor_bet_id` ASC) USING BTREE,
  INDEX `idx_vendor_bet_time`(`vendor_bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13929 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Spribe原始注单记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_tc_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_tc_bet_raw_log`;
CREATE TABLE `tb_tc_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_detail_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号详细讯息代码',
  `game_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '彩种编码',
  `numero` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '期号',
  `order_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号(后台查询)',
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏账号的登录名',
  `merchant_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户代码',
  `game_group_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '彩种组',
  `plan_bet_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划投注金额',
  `order_content_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号内容代码',
  `order_master_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主订单代码',
  `bet_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注金额 (备用栏位，暂时回传 null 值)',
  `trans_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注时间',
  `chase` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '追号标志 (0=无追号，1=追号)',
  `multiple` decimal(8, 2) NULL DEFAULT NULL COMMENT '倍数',
  `play_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '彩种名称，备注',
  `total_bet` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总投注注数',
  `series` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '系列值',
  `max_series` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最大系列值',
  `betting_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注实际内容（CLOB最大2GB）',
  `play_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩法代码',
  `freeze_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冻结时间',
  `actual_bet_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际投注金额',
  `win_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '中奖金额',
  `plan_win_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划中奖金额',
  `rebate_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注反水',
  `result` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结果（4=已中奖，5=未中奖，16=和局，17=后台撤单）',
  `draw_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开奖时间',
  `exceed_win_amount` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '超额中奖金额',
  `winning_number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开奖号码',
  `client_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家IP',
  `play_bonus` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `single` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否为单式注单（true: 是，false: 否）',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `odds` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率',
  `bet_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注时间',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `bet_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单状态\r\n(1:WIN | 2:LOSE | 3:CANCELLED | 4:TIE )\r\n(1:已中奖｜2:未中奖｜3:取消 | 4:和)',
  `bet_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注数',
  `lottery_type_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '彩种组',
  `settlement_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算时间',
  `net_pnl` decimal(20, 2) NULL DEFAULT NULL COMMENT '净输赢',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_num_index`(`order_num` ASC) USING BTREE,
  INDEX `idx_trans_time`(`trans_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2085 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'TC原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_tf_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_tf_bet_raw_log`;
CREATE TABLE `tb_tf_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `bet_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单号',
  `odds` decimal(24, 2) NULL DEFAULT NULL COMMENT '赔率(连串/OR/1x2/SPOR为欧盘赔率，否则为马来赔率)',
  `malay_odds` decimal(24, 2) NULL DEFAULT NULL COMMENT '马来赔率(连串为null)',
  `euro_odds` decimal(24, 2) NULL DEFAULT NULL COMMENT '欧盘赔率',
  `member_odds` decimal(24, 4) NULL DEFAULT NULL COMMENT '会员下的赔率',
  `member_odds_style` enum('euro','hongkong','indo','malay') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会员下的盘',
  `game_type_id` int(11) NULL DEFAULT NULL COMMENT '游戏ID',
  `game_type_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `game_market_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口名称',
  `market_option` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口局分',
  `map_num` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第几局',
  `bet_type_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口类型',
  `competition_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '比赛名称',
  `event_id` int(11) NULL DEFAULT NULL COMMENT '赛事ID',
  `event_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赛事名称',
  `event_datetime` datetime NULL DEFAULT NULL COMMENT '赛事开始时间(UTC)',
  `date_created` datetime NULL DEFAULT NULL COMMENT '下注时间(UTC)',
  `settlement_datetime` datetime NULL DEFAULT NULL COMMENT '结算时间(UTC)',
  `modified_datetime` datetime NULL DEFAULT NULL COMMENT '更改时间(UTC)',
  `bet_selection` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注选项',
  `currency` char(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货币',
  `amount` decimal(24, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `settlement_status` enum('confirmed','settled','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单状况',
  `is_unsettled` tinyint(1) NULL DEFAULT NULL COMMENT '是否已重新结算',
  `result_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单结果',
  `full_result_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单结果(详细)',
  `result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口结果',
  `earnings` decimal(24, 2) NULL DEFAULT NULL COMMENT '输赢额(建议用member_win_loss)',
  `handicap` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '让分数',
  `member_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会员号',
  `request_source` enum('desktop-browser','mobile-browser','mobile-app','unknown') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注的管道',
  `is_combo` tinyint(1) NULL DEFAULT NULL COMMENT '是否连串',
  `ticket_type` enum('db','live') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单下注状况',
  `tickets` json NULL COMMENT '连串注单详情(JSON格式)',
  `mini_game_table_id` int(11) NULL DEFAULT NULL COMMENT '小游戏桌子ID',
  `mini_game_table_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '小游戏桌子名',
  `event_sid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏前端克制赛事显示ID',
  `jackpot_type` int(11) NULL DEFAULT NULL COMMENT '奖池类型(0,1,2,3)',
  `jackpot_type_name` enum('coin','mini','minor','major') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖池类型名称',
  `jackpot_amount` decimal(24, 2) NULL DEFAULT NULL COMMENT '奖池金额',
  `member_win_loss_f` decimal(24, 2) NULL DEFAULT NULL COMMENT '会员输赢(本地货币)',
  `member_win_loss_l` decimal(24, 2) NULL DEFAULT NULL COMMENT '会员输赢(RMB)',
  `tax_amount` decimal(24, 2) NULL DEFAULT NULL COMMENT '小游戏税(本地货币)',
  `ticket_sid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏前端克制注单显示ID',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注單json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_tf_bet_raw_log_bet_id_IDX`(`bet_id` ASC) USING BTREE,
  INDEX `idx_date_created`(`date_created` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8206 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'TF投注记录原始表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_tp_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_tp_bet_raw_log`;
CREATE TABLE `tb_tp_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `hall` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '遊戲廠商',
  `rowid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注單單號 (同遊戲商內注單唯一值)',
  `round` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '遊戲局號',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '遊戲分類',
  `gameid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '遊戲代碼',
  `game_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '遊戲名稱',
  `casino_account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家帳號',
  `betvalid` decimal(15, 2) NULL DEFAULT NULL COMMENT '有效投注金額',
  `betamount` decimal(15, 2) NULL DEFAULT NULL COMMENT '投注金額',
  `betresult` decimal(15, 2) NULL DEFAULT NULL COMMENT '派彩金額',
  `pca_contribute` decimal(15, 2) NULL DEFAULT NULL COMMENT '彩池貢獻金',
  `pca_win` decimal(15, 2) NULL DEFAULT NULL COMMENT '彩池中獎金額',
  `revenue` decimal(15, 2) NULL DEFAULT NULL COMMENT '抽水金額',
  `bettime` datetime NULL DEFAULT NULL COMMENT '投注時間',
  `payout_time` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '派彩時間 (Optional)',
  `reporttime` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注單爬回時間',
  `trace` tinyint(1) NULL DEFAULT NULL COMMENT '是否追號 (true = 是, false = 否)',
  `freegame` tinyint(1) NULL DEFAULT NULL COMMENT '是否包含免費遊戲 (0:不包含, 1:包含, 預設為null:未提供)',
  `bettype` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '下注類型，請參考附錄文件 (預設為null:未提供)',
  `gameresult` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '遊戲結果，請參考附錄文件 (預設為null:未提供)',
  `betinfo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注單相關資訊 (null: 未提供, qishu: 遊戲期數)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注單狀態 (0:未派彩, 1:已派彩, 2:已派彩但注單修改過, 3:撤單)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '創建時間',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新時間',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_tp_bet_raw_log_rowid_IDX`(`rowid` ASC) USING BTREE,
  INDEX `idx_reporttime`(`reporttime` ASC) USING BTREE,
  INDEX `idx_bettime`(`bettime` ASC) USING BTREE,
  INDEX `idx_casino_account`(`casino_account` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20437 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '遊戲注單原始日誌表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_turbo_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_turbo_bet_raw_log`;
CREATE TABLE `tb_turbo_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `cmd` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '命令：CallBalance/pointinout/timeoutbetreturn',
  `api_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代理商标识符',
  `user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏账号',
  `money` decimal(18, 4) NULL DEFAULT NULL COMMENT '原始请求金额（无符号）',
  `create_timestamp` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始时间戳（秒）',
  `dealid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易唯一ID',
  `code` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '加扣点类型：1-加点，2-扣点',
  `roundid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏回合ID',
  `finished` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏是否结束：1/true结束，0/false未结束',
  `betinfo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注信息',
  `gameinfo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏ID(token)',
  `bet_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '下注金额（扣点）',
  `bet_time` bigint(20) NULL DEFAULT NULL COMMENT '下注时间（毫秒）',
  `win_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '派彩金额（加点）',
  `settle_time` bigint(20) NULL DEFAULT NULL COMMENT '结算时间（毫秒）',
  `order_status` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '订单状态：10-未结算，20-已结算，30-已取消',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_dealid`(`dealid` ASC) USING BTREE,
  INDEX `idx_user`(`user` ASC) USING BTREE,
  INDEX `idx_order_status`(`order_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Turbo交易原始注单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tb_ug_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_ug_bet_raw_log`;
CREATE TABLE `tb_ug_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注单ID',
  `ticket_group_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主注单ID',
  `user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家帐号',
  `currency_id` int(11) NULL DEFAULT NULL COMMENT '货币代码',
  `status` int(11) NULL DEFAULT NULL COMMENT '注单状态',
  `payout` decimal(15, 4) NULL DEFAULT NULL COMMENT '赔付金额',
  `stake` decimal(15, 4) NULL DEFAULT NULL COMMENT '下注金额',
  `net_stake` decimal(15, 4) NULL DEFAULT NULL COMMENT '实际下注金额',
  `turnover` decimal(15, 4) NULL DEFAULT NULL COMMENT '有效投注金额',
  `win_lose` decimal(15, 4) NULL DEFAULT NULL COMMENT '注单输赢金额(含保险输赢金额)',
  `odds_expression` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率样式',
  `odds_expression_short_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赔率样式短名',
  `bet_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注时间',
  `bet_update_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单输赢结果',
  `group_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '佣金组别',
  `ticket_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单类型',
  `parlay_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Parlay 类型名称',
  `remaining_stake` decimal(15, 4) NULL DEFAULT NULL COMMENT '剩余金额',
  `remaining_net_stake` decimal(15, 4) NULL DEFAULT NULL COMMENT '实际剩余金额',
  `is_internal` tinyint(1) NULL DEFAULT NULL COMMENT '是否为内部帐号',
  `item_count` int(11) NULL DEFAULT NULL COMMENT '赛事数',
  `bet_count` int(11) NULL DEFAULT NULL COMMENT '注数',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注IP',
  `sell_stake` decimal(15, 4) NULL DEFAULT NULL COMMENT '累计出售金额',
  `report_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报表时间',
  `agent_id` int(11) NULL DEFAULT NULL COMMENT '代理 ID',
  `sort_no` int(11) NULL DEFAULT NULL COMMENT '排序编号',
  `market_category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘口类型',
  `refund_net_stake` decimal(15, 4) NULL DEFAULT NULL COMMENT '累计实际退款金额',
  `settle_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算时间',
  `parlay_odds` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Parlay 赔率',
  `quick_bet` int(11) NULL DEFAULT NULL COMMENT '是否为快速投注(1-是,0-否)',
  `web_type` int(11) NULL DEFAULT NULL COMMENT '下注装置版本',
  `is_ug_combo` tinyint(1) NULL DEFAULT NULL COMMENT '是否为串关UG組合',
  `resettle_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '重新结算前原结算资讯(JSON数组)',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注子单列表(JSON数组)',
  `insurance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '保险单列表(JSON数组)',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始响应JSON',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ticket_id`(`ticket_id` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21121 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'UG原始注单记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_v8_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_v8_bet_raw_log`;
CREATE TABLE `tb_v8_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `game_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏局号',
  `account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家账号',
  `server_id` int(11) NULL DEFAULT NULL COMMENT '游戏房间ID',
  `kind_id` int(11) NULL DEFAULT NULL COMMENT '游戏类型ID',
  `table_id` bigint(20) NULL DEFAULT NULL COMMENT '桌子号',
  `chair_id` int(11) NULL DEFAULT NULL COMMENT '椅子号',
  `user_count` int(11) NULL DEFAULT NULL COMMENT '玩家数量',
  `cell_score` decimal(18, 4) NULL DEFAULT NULL COMMENT '有效下注金额',
  `all_bet` decimal(18, 4) NULL DEFAULT NULL COMMENT '总下注金额',
  `profit` decimal(18, 4) NULL DEFAULT NULL COMMENT '盈利金额',
  `revenue` decimal(18, 4) NULL DEFAULT NULL COMMENT '抽水金额',
  `game_start_time` datetime NULL DEFAULT NULL COMMENT '游戏开始时间',
  `game_end_time` datetime NULL DEFAULT NULL COMMENT '游戏结束时间',
  `card_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '手牌和公共牌(JSON格式)',
  `channel_id` int(11) NULL DEFAULT NULL COMMENT '渠道ID',
  `line_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家所属站点代码',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种',
  `language` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏语言',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_v8_bet_raw_log_game_id_IDX`(`game_id` ASC) USING BTREE,
  INDEX `idx_game_start_time`(`game_start_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4708 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'V8投注记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_va_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_va_bet_raw_log`;
CREATE TABLE `tb_va_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '状态',
  `version_key` int(11) NOT NULL DEFAULT 0 COMMENT '版本键',
  `bet_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注ID',
  `channel_id` int(11) NOT NULL COMMENT '渠道ID',
  `account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币',
  `game_id` int(11) NOT NULL COMMENT '游戏ID',
  `game_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏类型',
  `bet` decimal(18, 2) NOT NULL COMMENT '投注金额',
  `payout` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '派彩金额',
  `win_lose` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '输赢金额',
  `free_game` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '免费游戏标识',
  `bet_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'main' COMMENT '投注模式',
  `bet_time` datetime NOT NULL COMMENT '投注时间',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_va_bet_raw_log_bet_id_IDX`(`bet_id` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22469 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '投注记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_venues
-- ----------------------------
DROP TABLE IF EXISTS `tb_venues`;
CREATE TABLE `tb_venues`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `venue_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆code',
  `venue_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场馆名称',
  `category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏分类code',
  `gp_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏供应商code',
  `gp_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属厂商name',
  `logo_web` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `logo_h5` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `combine_time` bigint(20) NULL DEFAULT NULL COMMENT '厂商关联场馆时间',
  `combine_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联操作人',
  `remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  `use_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `maintain_remark` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护备注，关联remark_type',
  `disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '停止/维护触发时间',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `status_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维护/停用/异常时间 展示',
  `maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间起始',
  `maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '维护时间结束',
  `remark` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `updater` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `maintain_trigger_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录触发维护状态时，上一个使用状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `source_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLED' COMMENT '状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `show_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT '显示-\"Y\";隐藏-\"N\"',
  `sort` int(11) NOT NULL DEFAULT 9999 COMMENT '排序接口',
  `source_status_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆源 --维护/停用/异常时间 展',
  `source_maintain_start_time` bigint(20) NULL DEFAULT NULL COMMENT '场馆源 --维护时间起始',
  `source_maintain_end_time` bigint(20) NULL DEFAULT NULL COMMENT '场馆源 --维护时间结束',
  `source_disabled_time` bigint(20) NULL DEFAULT NULL COMMENT '场馆源 --停止时间',
  `maintain_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护;1-临时维护;2-游戏厂商下架;3-运营要求下架;4-其他',
  `source_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆源备注类型：0：例行维护;1-临时维护;2-游戏厂商下架;3-运营要求下架;4-其他',
  `source_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆源备注',
  `source_maintain_remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆源备注类型：0：例行维护;1-临时维护;2-游戏厂商下架;3-运营要求下架;4-其他',
  `source_maintain_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆源维护备注',
  `maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAIN' COMMENT '场馆列表-维护状态：维护--MAINTAIN;不维护--NOT_MAINTAIN',
  `source_maintain_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NOT_MAINTAIN' COMMENT '场馆源--维护状态：维护--MAINTAIN;不维护--NOT_MAINTAIN',
  `jump_type` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跳转类型：INLINE-内联；NEW_WINDOW-新窗口',
  `line_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线路链接',
  `is_use_sys_icon` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT '否使用系统图标 N-使用自定义图标，Y-使用系统图标',
  `custom_logo_web` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `custom_logo_h5` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `venue_code_index`(`venue_code` ASC) USING BTREE,
  UNIQUE INDEX `gpcode_categcode_index`(`gp_code` ASC, `category_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 193 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '场馆表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_venues_source
-- ----------------------------
DROP TABLE IF EXISTS `tb_venues_source`;
CREATE TABLE `tb_venues_source`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `venues_id` bigint(20) NULL DEFAULT NULL COMMENT '场馆id',
  `remark` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `sort` int(11) NULL DEFAULT NULL COMMENT '游戏排序值',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态： 正常-- ENABLED；维护--MAINTAIN；停用--DISABLED',
  `logo_web` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'web端图标',
  `logo_h5` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'h5图标',
  `venues_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆code',
  `venues_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场馆名称',
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类code',
  `gp_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属厂商name',
  `gp_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属厂商code',
  `remark_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注类型：0：例行维护；1-临时维护；2-游戏厂商下架；3-运营要求下架；4-其他',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '场馆源' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_vr_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_vr_bet_raw_log`;
CREATE TABLE `tb_vr_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `serial_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注订单号',
  `player_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家名称（英文字母和数字）',
  `merchant_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户代码',
  `merchant_prize` decimal(15, 3) NOT NULL,
  `player_prize` decimal(15, 3) NOT NULL,
  `loss_prize` decimal(15, 3) NOT NULL COMMENT '重新颁奖损失，精确至小数第三位',
  `state` tinyint(4) NOT NULL COMMENT '投注状态(0:未颁奖, 1:撤单, 2:未中奖, 3:中奖)',
  `sub_state` int(11) NULL DEFAULT NULL COMMENT '次级状态，bit表示(1:玩家撤单, 2:管理员撤单, 4:整期撤单, 8:重新颁奖, 16:和局)',
  `unit` decimal(8, 3) NOT NULL COMMENT '投注单位(2元、1元、0.2角、0.1角、0.02分、0.01分、0.002厘、0.001厘)',
  `multiple` int(11) NOT NULL COMMENT '投注倍数',
  `count` int(11) NOT NULL COMMENT '投注注数',
  `cost` decimal(15, 3) NOT NULL COMMENT '投注金额',
  `odds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '赔率(显示的奖金数字，可能是中文)',
  `player_odds` int(11) NOT NULL,
  `number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投注数字(内容可能是中文)',
  `position` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注位置(内容可能是中文)',
  `channel_id` int(11) NOT NULL,
  `channel_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `channel_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `bet_type_code` int(11) NOT NULL,
  `bet_type_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `issue_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `winning_number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `note` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注(内容可能是中文)',
  `create_time` datetime NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `ip` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家投注IP',
  `prize_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `created_at` bigint(20) NULL DEFAULT NULL COMMENT '记录创建时间',
  `updated_at` bigint(20) NULL DEFAULT NULL COMMENT '记录更新时间',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `bet_serial_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '追号的原始主订单号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_vr_bet_raw_log_serial_number_IDX`(`serial_number` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4920 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VR投注原始日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_wg_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_wg_bet_raw_log`;
CREATE TABLE `tb_wg_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '游戏记录编号(唯一码)',
  `account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '玩家账号',
  `server_id` int(11) NULL DEFAULT NULL COMMENT '房间ID',
  `kind_id` int(11) NULL DEFAULT NULL COMMENT '游戏ID',
  `table_id` int(11) NULL DEFAULT NULL COMMENT '桌子号',
  `chair_id` int(11) NULL DEFAULT NULL COMMENT '椅子号',
  `user_count` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '椅子号',
  `card_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '手牌公共牌',
  `cell_score` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有效下注',
  `all_bet` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总下注',
  `profit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盈利',
  `revenue` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽水',
  `order_type` int(11) NULL DEFAULT NULL COMMENT '注单类型(1:游戏结算 6:瓜分彩金池)',
  `p_order_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单号',
  `cur_count` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投注后玩家余额',
  `client_type` int(11) NULL DEFAULT NULL COMMENT '客户端类型(2 2D客户端 3 3D客户端)',
  `game_start_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏开始时间',
  `game_end_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏结束时间',
  `line_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区分标识',
  `keep_win` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '连胜标识，json字符串',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '记录创建时间（Unix 时间戳）',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '记录更新时间（Unix 时间戳）',
  `deleted` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录是否已删除',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `category_id` int(11) NULL DEFAULT NULL COMMENT '分类id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_kind_id`(`kind_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_server_id`(`server_id` ASC) USING BTREE,
  INDEX `idx_table_id`(`table_id` ASC) USING BTREE,
  INDEX `idx_order_type`(`order_type` ASC) USING BTREE,
  INDEX `idx_account`(`account` ASC) USING BTREE,
  INDEX `idx_p_order_id`(`p_order_id` ASC) USING BTREE,
  INDEX `record_id_idx`(`record_id` ASC) USING BTREE,
  INDEX `idx_game_start_time`(`game_start_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 295663 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WG原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_wm_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_wm_bet_raw_log`;
CREATE TABLE `tb_wm_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账号',
  `bet_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单号',
  `bet_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注时间',
  `before_cash` decimal(10, 2) NULL DEFAULT NULL COMMENT '下注前金额',
  `bet` decimal(10, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `validbet` decimal(10, 2) NULL DEFAULT NULL COMMENT '有效下注',
  `water` decimal(10, 2) NULL DEFAULT NULL COMMENT '退水金额',
  `result` decimal(10, 2) NULL DEFAULT NULL COMMENT '下注结果',
  `bet_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注代码',
  `bet_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下注内容',
  `water_bet` decimal(10, 2) NULL DEFAULT NULL COMMENT '下注退水金额',
  `win_loss` decimal(10, 2) NULL DEFAULT NULL COMMENT '输赢金额',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP',
  `gid` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏类别编号',
  `event` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次编号',
  `event_child` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子场次编号',
  `round` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次编号',
  `sub_round` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '牌型',
  `table_id` int(11) NULL DEFAULT NULL COMMENT '桌台编号',
  `commission` decimal(10, 2) NULL DEFAULT NULL COMMENT '0:一般, 1:免佣',
  `settime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算时间',
  `reset` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Y:有重对, N:非重对',
  `game_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏结果',
  `gname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游戏名称',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `bet_id_index`(`bet_id` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 887 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WM投原始注单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_ws_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_ws_bet_raw_log`;
CREATE TABLE `tb_ws_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
