  `match_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '赛事ID',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注单状态',
  `bet_amount` decimal(14, 2) NULL DEFAULT NULL COMMENT '下注金额',
  `valid_amount` decimal(14, 2) NULL DEFAULT NULL COMMENT '有效投注',
  `net_income` decimal(14, 2) NULL DEFAULT NULL COMMENT '净收入',
  `bet_return` decimal(14, 2) NULL DEFAULT NULL COMMENT '返还金额',
  `locale_bet_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本地化下注类型',
  `locale_channel` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本地化渠道',
  `locale_game_result` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本地化赛果',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注单json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_ws_bet_raw_log_bet_id_IDX`(`bet_id` ASC) USING BTREE,
  INDEX `idx_bet_at`(`bet_at` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 247 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WS原始注单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_ygr_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_ygr_bet_raw_log`;
CREATE TABLE `tb_ygr_bet_raw_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `account` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩家唯一識別值',
  `agent_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代理ID',
  `wagers_id` bigint(20) UNSIGNED NOT NULL COMMENT '在遊戲商系統的交易唯一值',
  `game_id` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '遊戲的唯一識別值',
  `wagers_time` datetime NOT NULL COMMENT '投注時間 (對帳可依此時間結算)',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投注幣別',
  `bet_amount` decimal(18, 2) NOT NULL COMMENT '投注金額',
  `payoff_time` datetime NOT NULL COMMENT '派彩時間',
  `payoff_amount` decimal(18, 2) NOT NULL COMMENT '派彩金額',
  `bef_amount` decimal(18, 2) NOT NULL COMMENT '投注前會員額度',
  `aft_amount` decimal(18, 2) NOT NULL COMMENT '投注後會員額度',
  `status` tinyint(3) UNSIGNED NOT NULL COMMENT '注單狀態:1-贏,2-輸,3-和',
  `valid_amount` decimal(18, 2) NOT NULL COMMENT '有效投注',
  `settlement_time` datetime NOT NULL COMMENT '對帳時間(每月記帳用來區分注單是歸類在哪個月份的時間)',
  `jackpot` decimal(18, 2) NOT NULL COMMENT '彩金',
  `contribution` decimal(18, 2) NOT NULL COMMENT '貢獻金',
  `game_category_id` tinyint(3) UNSIGNED NOT NULL COMMENT '遊戲類型:1-電子,2-真人,3-彩票,4-體育,5-捕魚,6-棋牌',
  `version_key` int(10) UNSIGNED NOT NULL COMMENT '版本號',
  `resp_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '注單json',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '創建人',
  `create_time` bigint(20) NULL DEFAULT NULL COMMENT '創建時間',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` bigint(20) NULL DEFAULT NULL COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_ygr_bet_raw_log_wagers_id_IDX`(`wagers_id` ASC) USING BTREE,
  INDEX `idx_wagers_time`(`wagers_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6486 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'YGR遊戲注單記錄' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for tb_z88_bet_raw_log
-- ----------------------------
DROP TABLE IF EXISTS `tb_z88_bet_raw_log`;
CREATE TABLE `tb_z88_bet_raw_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '玩家账号',
  `game_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '游戏ID',
  `round_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '游戏局号/回合ID',
  `txn_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易流水号',
  `timestamp` datetime NULL DEFAULT NULL COMMENT '时间',
  `action_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '动作类型：BET/WIN',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '币种，如 SGD',
  `bet_amount` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '下注金额',
  `win_amount` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '赢得金额',
  `amount` decimal(18, 4) NOT NULL COMMENT '账户变动金额（可正可负）',
  `bet_time` datetime NOT NULL COMMENT '下注时间',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `checksum` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '校验值（签名/防篡改）',
  `resp_json` json NULL COMMENT '原始请求数据',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '更新时间',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_txn_id`(`txn_id` ASC) USING BTREE,
  INDEX `idx_bet_time`(`bet_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Z88原始注单表' ROW_FORMAT = Dynamic;

