) ENGINE = InnoDB AUTO_INCREMENT = 321 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Event structure for drop_partition
-- ----------------------------
DROP EVENT IF EXISTS `drop_partition`;
delimiter ;;
CREATE EVENT `drop_partition`
ON SCHEDULE
EVERY '1' DAY STARTS '2026-01-15 14:35:00'
ON COMPLETION PRESERVE
DO BEGIN
set @pname = concat('alter table tb_game_bet_order_std drop partition _p', DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 50 DAY), '%Y%m%d%H%i%s'));
prepare stmt_drop_partition from @pname;
execute stmt_drop_partition;
deallocate prepare stmt_drop_partition;
END
;;
delimiter ;

-- ----------------------------
-- Event structure for drop_tb_game_bet_order_std_partition
-- ----------------------------
DROP EVENT IF EXISTS `drop_tb_game_bet_order_std_partition`;
delimiter ;;
CREATE EVENT `drop_tb_game_bet_order_std_partition`
ON SCHEDULE
EVERY '1' DAY STARTS '2025-10-01 12:00:00'
ON COMPLETION PRESERVE
DO BEGIN
set @pname = concat('alter table orders tb_game_bet_order_std partition _p', DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 40 DAY), '%Y%m%d%H%i%s'));
prepare stmt_drop_tb_game_bet_order_std_partition from @pname;
execute stmt_drop_tb_game_bet_order_std_partition;
deallocate prepare drop_tb_game_bet_order_std_partition;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
